INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0675', 'فیله کمر معکوس (روی توپ تعادلی)', 'Reverse hyper extension (on stability ball)', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. دمر روی توپ تعادلی دراز بکشید، لگن روی توپ و پاها صاف پشت سر باشد.
۲. برای ثبات دست‌ها را جلوی خود روی زمین بگذارید.
۳. با درگیر کردن باسن و همسترینگ، پاها را تا جای ممکن به سمت سقف بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0675.gif', 'gluteal', 'hamstring,lower-back', '1. Lie face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.
2. Place your hands on the ground in front of you for stability.
3. Engaging your glutes and hamstrings, lift your legs up towards the ceiling as high as you can.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0675') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1423', 'فیله کمر معکوس روی نیمکت صاف', 'Reverse hyper on flat bench', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. روی نیمکت صاف دمر دراز بکشید، لگن در لبه و پاها از نیمکت آویزان باشد.
۲. برای ثبات نیمکت را بگیرید.
۳. با پاهای صاف، آن‌ها را تا جای ممکن به سمت سقف بالا ببرید.
۴. در اوج حرکت باسن را منقبض کنید.
۵. پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1423.gif', 'gluteal', 'hamstring,lower-back', '1. Lie face down on a flat bench with your hips at the edge and your legs hanging off the bench.
2. Hold onto the bench for stability.
3. Keeping your legs straight, raise them up towards the ceiling as high as you can.
4. Squeeze your glutes at the top of the movement.
5. Slowly lower your legs back down to the starting position.
6. Repeat for the desired number of repetitions.', '1423') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3663', 'پلانک معکوس با بالا آوردن پا', 'Reverse plank with leg lift', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'سرینی (باسن)، همسترینگ (پشت ران)، شانه‌ها', '۱. روی زمین بنشینید، پاها را جلوی بدن صاف کنید و دست‌ها را پشت سر با انگشتان رو به پاها روی زمین بگذارید.
۲. با فشار دست‌ها لگن را از زمین بلند کنید و به حالت پلانک معکوس بروید.
۳. میان‌تنه را درگیر کنید و یک پا را از زمین بلند کنید و صاف به سمت سقف ببرید.
۴. لحظه‌ای نگه دارید، سپس پا را پایین بیاورید.
۵. با پای دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3663.gif', 'abs', 'gluteal,hamstring,deltoids', '1. Sit on the ground with your legs extended in front of you and your hands resting on the ground behind you, fingers pointing towards your feet.
2. Press through your hands and lift your hips off the ground, coming into a reverse plank position.
3. Engage your core and lift one leg off the ground, extending it straight up towards the ceiling.
4. Hold for a moment, then lower your leg back down.
5. Repeat with the other leg.
6. Continue alternating legs for the desired number of repetitions.', '3663') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0677', 'دیپ حلقه', 'Ring dips', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. از حلقه‌ها با دست‌های کاملاً صاف و بدن صاف آویزان شوید.
۲. با خم کردن آرنج‌ها بدن را پایین ببرید تا شانه‌ها پایین‌تر از آرنج‌ها قرار گیرند.
۳. با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0677.gif', 'triceps', 'chest,deltoids', '1. Start by hanging from the rings with your arms fully extended and your body straight.
2. Lower your body by bending your elbows until your shoulders are below your elbows.
3. Push yourself back up to the starting position by straightening your arms.
4. Repeat for the desired number of repetitions.', '0677') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2571', 'کشش قورباغه‌ای نوسانی', 'Rocking frog stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. روی زمین زانو بزنید و زانوها را به اندازه عرض لگن باز کنید.
۲. برای حمایت دست‌ها را جلوی خود روی زمین بگذارید.
۳. آرام به جلو متمایل شوید، وزن را روی دست‌ها ببرید و پاها را پشت سر دراز کنید.
۴. کمر را صاف نگه دارید و باسن را درگیر کنید و لگن را به عقب و بالا به سمت سقف ببرید.
۵. این وضعیت را چند ثانیه نگه دارید و کشش را در باسن حس کنید.
۶. با خم کردن زانوها و پایین آوردن لگن آرام به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2571.gif', 'gluteal', 'hamstring,quadriceps', '1. Start by kneeling on the ground with your knees hip-width apart.
2. Place your hands on the ground in front of you for support.
3. Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.
4. Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.
5. Hold this position for a few seconds, feeling a stretch in your glutes.
6. Slowly return to the starting position by bending your knees and lowering your hips back down.
7. Repeat for the desired number of repetitions.', '2571') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0678', 'بارفیکس راکی', 'Rocky pull-up pulldown', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. جلوی میله بارفیکس بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دست‌ها را بالا ببرید و میله را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با دست‌های کاملاً صاف و بدن صاف از میله آویزان شوید.
۴. عضلات پشت را درگیر کنید و با هدایت سینه بدن را به سمت میله بالا بکشید.
۵. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0678.gif', 'upper-back', 'biceps,forearm', '1. Stand in front of a pull-up bar with your feet shoulder-width apart.
2. Reach up and grab the bar with an overhand grip, slightly wider than shoulder-width apart.
3. Hang from the bar with your arms fully extended and your body straight.
4. Engage your back muscles and pull your body up towards the bar, leading with your chest.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0678') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2208', 'کشش کمر با فوم‌رولر', 'Roller back stretch', 'back', 'پشت و زیربغل', 'other', 'سایر', 'فیله کمر', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. روی زمین بنشینید و پاها را جلوی بدن دراز کنید.
۲. فوم‌رولر را عمود بر بدن، درست زیر باسن قرار دهید.
۳. بدن را آرام به عقب بغلتانید تا رولر روی کمر بالا برود.
۴. تا جایی ادامه دهید که رولر به بالای کمر برسد.
۵. لحظه‌ای مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2208.gif', 'lower-back', 'hamstring,gluteal', '1. Start by sitting on the ground with your legs extended in front of you.
2. Place the roller perpendicular to your body, just below your glutes.
3. Slowly roll your body backwards, allowing the roller to move up your back.
4. Continue rolling until the roller reaches your upper back.
5. Pause for a moment, then slowly roll back to the starting position.
6. Repeat for the desired number of repetitions.', '2208') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2204', 'اره بدن با فوم‌رولر', 'Roller body saw', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'شانه‌ها، پشت بازو، میان‌تنه', '۱. در حالت پلانک با ساعدها روی رولر و بدن در یک خط صاف قرار بگیرید.
۲. میان‌تنه را درگیر کنید و رولر را آرام به جلو بغلتانید و بدن را تا جایی که کنترل دارید باز کنید.
۳. لحظه‌ای در دورترین نقطه مکث کنید، سپس رولر را آرام به وضعیت شروع برگردانید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2204.gif', 'abs', 'deltoids,triceps', '1. Start in a plank position with your forearms on the roller and your body in a straight line.
2. Engage your core and slowly roll the roller forward, extending your body as far as you can while maintaining control.
3. Pause for a moment at the furthest point, then slowly roll the roller back towards your starting position.
4. Repeat for the desired number of repetitions.', '2204') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2205', 'کشش لگن و زیربغل با فوم‌رولر', 'Roller hip lat stretch', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. روی زمین زانو بزنید و رولر را زیر لگن قرار دهید.
۲. برای حمایت دست‌ها را روی رولر بگذارید.
۳. رولر را آرام به جلو بغلتانید، لگن را باز کنید و باسن را بکشید.
۴. کشش را چند ثانیه نگه دارید، سپس به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2205.gif', 'gluteal', 'hamstring,quadriceps', '1. Start by kneeling on the ground with the roller positioned under your hips.
2. Place your hands on the roller for support.
3. Slowly roll the roller forward, extending your hips and stretching your glutes.
4. Hold the stretch for a few seconds, then roll back to the starting position.
5. Repeat for the desired number of repetitions.', '2205') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2202', 'کشش لگن با فوم‌رولر', 'Roller hip stretch', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. روی زمین بنشینید و پاها را جلوی بدن دراز کنید.
۲. رولر را زیر باسن، کمی بالاتر از زانوها قرار دهید.
۳. به عقب تکیه دهید و برای حمایت دست‌ها را پشت سر روی زمین بگذارید.
۴. باسن را درگیر کنید و رولر را آرام به جلو بغلتانید، زانوها را خم کنید و به سمت سینه بیاورید.
۵. لحظه‌ای در انتهای حرکت مکث کنید و کشش را در باسن حس کنید.
۶. رولر را آرام به وضعیت شروع برگردانید و پاها را صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2202.gif', 'gluteal', 'hamstring,quadriceps', '1. Start by sitting on the ground with your legs extended in front of you.
2. Place the roller under your glutes, just above your knees.
3. Lean back and place your hands on the ground behind you for support.
4. Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.
5. Pause for a moment at the end of the movement, feeling a stretch in your glutes.
6. Slowly roll the roller back to the starting position, extending your legs.
7. Repeat for the desired number of repetitions.', '2202') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2206', 'کرانچ معکوس با فوم‌رولر', 'Roller reverse crunch', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، دست‌ها صاف بالای سر و پاها صاف جلوی بدن باشد.
۲. رولر را بین پاها قرار دهید و با پنجه‌ها نگه دارید.
۳. با درگیر کردن شکم، پاها را از زمین بلند کنید و زانوها را به سمت سینه جمع کنید و رولر را به سمت بدن بغلتانید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام پایین بیاورید و رولر را از بدن دور کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2206.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your arms extended straight above your head and your legs straight out in front of you.
2. Place the roller between your feet and grip it with your toes.
3. Engaging your abs, lift your legs off the ground and curl your knees towards your chest, rolling the roller towards your body.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position, rolling the roller away from your body.
5. Repeat for the desired number of repetitions.', '2206') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2203', 'تمرین کتف نشسته با فوم‌رولر', 'Roller seated shoulder flexor depresor retractor', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'سرشانه، پشت بازو', '۱. روی سطح صاف بنشینید و پاها را جلوی بدن دراز کنید.
۲. رولر را با دو دست و کف دست رو به پایین بگیرید و روی ران‌ها قرار دهید.
۳. کمی به جلو متمایل شوید و رولر را از بدن دور کنید و دست‌ها را صاف جلوی بدن دراز کنید.
۴. لحظه‌ای مکث کنید، سپس رولر را آرام به سمت بدن برگردانید و دست‌ها را خم کنید تا رولر به ران‌ها برسد.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2203.gif', 'chest', 'deltoids,triceps', '1. Sit on a flat surface with your legs extended in front of you.
2. Hold the roller with both hands, palms facing down, and place it on your thighs.
3. Lean forward slightly and roll the roller away from your body, extending your arms straight in front of you.
4. Pause for a moment, then slowly roll the roller back towards your body, bending your arms and bringing the roller back to your thighs.
5. Repeat for the desired number of repetitions.', '2203') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2209', 'تمرین کتف نشسته تک‌پا با فوم‌رولر', 'Roller seated single leg shoulder flexor depresor retractor', 'chest', 'سینه', 'other', 'سایر', 'سینه', 'سرشانه، پشت بازو', '۱. روی سطح صاف بنشینید و پاها را جلوی بدن دراز کنید.
۲. رولر را با دو دست و کف دست رو به پایین بگیرید و روی ران‌ها قرار دهید.
۳. کمی به عقب متمایل شوید و عضلات میان‌تنه را درگیر کنید.
۴. رولر را با دست‌های صاف تا سطح شانه بالا ببرید.
۵. رولر را آرام روی ران‌ها پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2209.gif', 'chest', 'deltoids,triceps', '1. Sit on a flat surface with your legs extended in front of you.
2. Hold the roller with both hands, palms facing down, and place it on your thighs.
3. Lean back slightly and engage your core muscles.
4. Raise the roller up to shoulder level, keeping your arms straight.
5. Slowly lower the roller back down to your thighs.
6. Repeat for the desired number of repetitions.', '2209') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2207', 'کشش زیربغل جانبی با فوم‌رولر', 'Roller side lat stretch', 'back', 'پشت و زیربغل', 'other', 'سایر', 'زیربغل', 'شانه‌ها، پشت بازو', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و رولر را با دو دست جلوی بدن نگه دارید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. دست‌ها را به جلو باز کنید و رولر را به سمت پاها پایین بغلتانید تا کشش را در زیربغل حس کنید.
۴. کشش را چند ثانیه نگه دارید، سپس رولر را آرام به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2207.gif', 'upper-back', 'deltoids,triceps', '1. Stand with your feet shoulder-width apart and hold the roller with both hands in front of your body.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Extend your arms forward and roll the roller down towards your feet, feeling a stretch in your lats.
4. Hold the stretch for a few seconds, then slowly roll the roller back up to the starting position.
5. Repeat for the desired number of repetitions.', '2207') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0680', 'بالا رفتن از طناب', 'Rope climb', 'back', 'پشت و زیربغل', 'other', 'سایر', 'بالای پشت', 'ساعد، جلو بازو، شانه‌ها', '۱. رو به طناب بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. طناب را با دو دست و کف دست رو به خود بگیرید.
۳. زانوها را کمی خم کنید و میان‌تنه را درگیر کنید.
۴. با جابه‌جایی دست‌ها یکی پس از دیگری، خود را از طناب بالا بکشید.
۵. برای کمک به بالا رفتن از پاها استفاده کنید.
۶. تا ارتفاع دلخواه یا بالای طناب ادامه دهید.
۷. برای پایین آمدن، حرکت دست‌ها را معکوس کنید و پایین آمدن را کنترل کنید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0680.gif', 'upper-back', 'forearm,biceps,deltoids', '1. Stand facing the rope with your feet shoulder-width apart.
2. Grab the rope with both hands, palms facing towards you.
3. Bend your knees slightly and engage your core.
4. Begin pulling yourself up the rope by alternating hand-over-hand movements.
5. Use your legs to assist in the upward movement.
6. Continue climbing until you reach the desired height or the top of the rope.
7. To descend, reverse the hand-over-hand movement while controlling your descent.
8. Repeat for the desired number of repetitions.', '0680') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1585', 'کشش دونده', 'Runners stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'ساق پا، چهارسر ران', '۱. بایستید و پاها را به اندازه عرض لگن باز کنید.
۲. با پای راست یک گام به جلو بردارید و پای چپ را ثابت نگه دارید.
۳. زانوی راست را خم کنید و بدن را پایین ببرید و پای چپ را صاف نگه دارید.
۴. برای حمایت دست‌ها را روی ران راست بگذارید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس طرف را عوض کرده و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1585.gif', 'hamstring', 'calves,quadriceps', '1. Stand with your feet hip-width apart.
2. Take a step forward with your right foot, keeping your left foot planted.
3. Bend your right knee and lower your body down, keeping your left leg straight.
4. Place your hands on your right thigh for support.
5. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '1585') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3012', 'دیپ کتف', 'Scapula dips', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'کول (ذوزنقه)', 'متوازی‌الاضلاع، سرشانه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را جلوی بدن دراز کنید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. با خم کردن آرنج‌ها و جمع کردن کتف‌ها بدن را پایین ببرید، گویی می‌خواهید مدادی را بین کتف‌ها نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با فشار دست‌ها آرنج‌ها را صاف کنید و به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3012.gif', 'trapezius', 'upper-back,deltoids', '1. Start by standing with your feet shoulder-width apart and your arms extended in front of you.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Lower your body by bending your elbows and retracting your shoulder blades, as if you are trying to squeeze a pencil between them.
4. Pause for a moment at the bottom, then push through your hands to extend your elbows and return to the starting position.
5. Repeat for the desired number of repetitions.', '3012') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3021', 'شنا سوئدی کتف', 'Scapula push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'دندانه‌ای قدامی', 'پشت بازو، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها درست زیر شانه‌ها و بدن در یک خط صاف.
۲. سینه را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک بدن نگه دارید.
۳. هنگام پایین رفتن کتف‌ها را به هم فشار دهید و سینه را به جلو بدهید.
۴. لحظه‌ای در پایین مکث کنید، سپس به وضعیت شروع بالا بروید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3021.gif', 'serratus', 'triceps,deltoids', '1. Start in a high plank position with your hands directly under your shoulders and your body in a straight line.
2. Lower your chest towards the ground, keeping your elbows close to your body.
3. As you lower, squeeze your shoulder blades together and push your chest forward.
4. Pause for a moment at the bottom, then push back up to the starting position.
5. Repeat for the desired number of repetitions.', '3021') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0688', 'بارفیکس کتف', 'Scapular pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'کول (ذوزنقه)', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. از میله بارفیکس با کف دست رو به جلو و دست‌های کاملاً صاف آویزان شوید.
۲. کتف‌ها را به پایین و عقب بکشید و جمع کنید.
۳. عضلات پشت را درگیر کنید و بدن را به سمت میله بالا بکشید و روی فشردن کتف‌ها به هم تمرکز کنید.
۴. لحظه‌ای در اوج حرکت مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0688.gif', 'trapezius', 'biceps,upper-back,deltoids', '1. Start by hanging from a pull-up bar with your palms facing away from you and your arms fully extended.
2. Retract your shoulder blades by pulling them down and back.
3. Engage your back muscles and pull your body up towards the bar, focusing on squeezing your shoulder blades together.
4. Pause for a moment at the top of the movement, then slowly lower your body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0688') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1390', 'کشش ساق پا نشسته', 'Seated calf stretch (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'همسترینگ (پشت ران)', '۱. لبه صندلی یا نیمکت بنشینید و کف پاها را روی زمین بگذارید.
۲. یک پا را صاف جلوی بدن دراز کنید و پاشنه را روی زمین نگه دارید.
۳. کمی به جلو متمایل شوید تا کشش را در عضلات ساق پا حس کنید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۵. پا را عوض کنید و کشش را تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1390.gif', 'calves', 'hamstring', '1. Sit on the edge of a chair or bench with your feet flat on the ground.
2. Extend one leg straight out in front of you, keeping your heel on the ground.
3. Lean forward slightly, feeling a stretch in your calf muscle.
4. Hold the stretch for 20-30 seconds.
5. Switch legs and repeat the stretch.', '1390') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1424', 'کشش سرینی نشسته', 'Seated glute stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)', '۱. روی زمین بنشینید و پاها را جلوی خود صاف دراز کنید.
۲. زانوی راست را خم کنید و مچ پای راست را روی ران چپ بگذارید.
۳. برای حمایت دست راست را پشت سر روی زمین بگذارید.
۴. با دست چپ زانوی راست را آرام به پایین فشار دهید تا کشش عمیق‌تر شود.
۵. کشش را ۳۰ ثانیه تا ۱ دقیقه نگه دارید.
۶. طرف را عوض کنید و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1424.gif', 'gluteal', 'hamstring', '1. Sit on the ground with your legs extended in front of you.
2. Bend your right knee and cross your right ankle over your left thigh.
3. Place your right hand on the ground behind you for support.
4. With your left hand, gently press down on your right knee to deepen the stretch.
5. Hold the stretch for 30 seconds to 1 minute.
6. Switch sides and repeat.', '1424') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0689', 'بالا آوردن پا نشسته', 'Seated leg raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. روی نیمکت صاف با کمر صاف بنشینید و کف پاها را روی زمین بگذارید.
۲. برای حمایت، دست‌ها را روی لبه‌های نیمکت بگذارید.
۳. با پاهای صاف، آن‌ها را آرام جلوی بدن بالا بیاورید تا موازی زمین شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0689.gif', 'abs', 'hip-flexors', '1. Sit on a flat bench with your back straight and your feet flat on the ground.
2. Place your hands on the sides of the bench for support.
3. Keeping your legs straight, slowly raise them up in front of you until they are parallel to the ground.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0689') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0690', 'کشش کمر نشسته', 'Seated lower back stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. لبه صندلی بنشینید و کف پاها را روی زمین بگذارید.
۲. برای حمایت دست‌ها را روی ران‌ها یا کناره‌های صندلی بگذارید.
۳. آرام از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۴. کشش را در پایین کمر حس کنید و ۲۰ تا ۳۰ ثانیه نگه دارید.
۵. آرام به وضعیت شروع برگردید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0690.gif', 'upper-back', 'gluteal,hamstring', '1. Sit on the edge of a chair with your feet flat on the ground.
2. Place your hands on your thighs or on the sides of the chair for support.
3. Slowly lean forward from your hips, keeping your back straight.
4. Feel the stretch in your lower back and hold for 20-30 seconds.
5. Slowly return to the starting position and repeat for the desired number of repetitions.', '0690') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2567', 'کشش پیریفورمیس نشسته', 'Seated piriformis stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)', '۱. روی زمین بنشینید و پاها را جلوی خود صاف دراز کنید.
۲. زانوی راست را خم کنید و پای راست را بیرون زانوی چپ بگذارید.
۳. آرنج چپ را بیرون زانوی راست بگذارید و تنه را آرام به راست بچرخانید.
۴. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس طرف را عوض کرده و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2567.gif', 'gluteal', 'hamstring', '1. Sit on the ground with your legs extended in front of you.
2. Bend your right knee and place your right foot on the outside of your left knee.
3. Place your left elbow on the outside of your right knee and gently twist your torso to the right.
4. Hold the stretch for 20-30 seconds, then switch sides and repeat.', '2567') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0691', 'کرانچ پهلو نشسته (به دیوار)', 'Seated side crunch (wall)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها', '۱. روی زمین بنشینید، کمر به دیوار و پاها جلوی بدن دراز باشد.
۲. زانوها را خم کنید و کف پاها را به اندازه عرض لگن روی زمین بگذارید.
۳. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۴. شکم را درگیر کنید و به یک طرف خم شوید و آرنج را به سمت لگن ببرید.
۵. لحظه‌ای مکث کنید، سپس به وضعیت شروع برگردید.
۶. حرکت را برای طرف دیگر تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0691.gif', 'abs', 'obliques', '1. Sit on the floor with your back against a wall and your legs extended in front of you.
2. Bend your knees and place your feet flat on the floor, hip-width apart.
3. Place your hands behind your head with your elbows pointing outwards.
4. Engage your abs and lean to one side, bringing your elbow towards your hip.
5. Pause for a moment, then return to the starting position.
6. Repeat on the other side.
7. Continue alternating sides for the desired number of repetitions.', '0691') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1587', 'توالی حالت زاویه باز نشسته', 'Seated wide angle pose sequence', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'چهارسر ران، ساق پا', '۱. روی زمین بنشینید و پاها را با زاویه باز دراز کنید.
۲. پنجه پاها را بالا بکشید و عضلات جلوی ران را درگیر کنید.
۳. برای حمایت دست‌ها را پشت سر روی زمین بگذارید.
۴. با کمر صاف از لگن به جلو خم شوید.
۵. تا جایی به جلو خم شوید که کشش را در همسترینگ حس کنید.
۶. این وضعیت را برای چند نفس نگه دارید.
۷. کشش را آرام رها کنید و به وضعیت شروع برگردید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1587.gif', 'hamstring', 'quadriceps,calves', '1. Sit on the ground with your legs extended in a wide angle.
2. Flex your feet and engage your quadriceps.
3. Place your hands on the ground behind you for support.
4. Keeping your back straight, lean forward from your hips.
5. Continue leaning forward until you feel a stretch in your hamstrings.
6. Hold this position for a few breaths.
7. Slowly release the stretch and return to the starting position.
8. Repeat for the desired number of repetitions.', '1587') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0697', 'پشت پا معکوس با کمک خود', 'Self assisted inverse leg curl', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)، ساق پا', '۱. به پشت صاف روی تشک یا نیمکت دراز بکشید و پاها را صاف کنید.
۲. برای حمایت دست‌ها را کنار بدن یا زیر باسن بگذارید.
۳. زانوها را خم کنید و پاها را از زمین بلند کنید و ران‌ها را به سمت سینه بیاورید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0697.gif', 'hamstring', 'gluteal,calves', '1. Lie flat on your back on a mat or bench with your legs extended.
2. Place your hands by your sides or under your glutes for support.
3. Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.
4. Pause for a moment at the top, then slowly lower your legs back to the starting position.
5. Repeat for the desired number of repetitions.', '0697') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1766', 'پشت پا معکوس با کمک خود (نسخه ۲)', 'Self assisted inverse leg curl', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)، ساق پا', '۱. روی دستگاه پشت پا دمر دراز بکشید، پاها صاف و مچ‌ها زیر اهرم پددار باشد.
۲. برای حمایت دست‌ها را روی دستگیره‌های کناری دستگاه بگذارید.
۳. بالاتنه را ثابت نگه دارید و با بازدم پاها را تا جای ممکن بالا بیاورید.
۴. وضعیت انقباض را لحظه‌ای نگه دارید و همسترینگ را بفشارید.
۵. با دم، پاها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1766.gif', 'hamstring', 'gluteal,calves', '1. Lie face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.
2. Place your hands on the side handles of the machine for support.
3. Keeping your upper body stationary, exhale and curl your legs upward as far as possible.
4. Hold the contracted position for a brief pause as you squeeze your hamstrings.
5. Slowly lower your legs back to the starting position while inhaling.
6. Repeat for the desired number of repetitions.', '1766') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0696', 'پشت پا معکوس با کمک خود (روی زمین)', 'Self assisted inverse leg curl (on floor)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)، ساق پا', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها کنار بدن باشد.
۲. زانوها را خم کنید و کف پاها را به اندازه عرض لگن روی زمین بگذارید.
۳. لگن را از زمین بلند کنید و باسن و همسترینگ را درگیر کنید.
۴. در حالی که لگن بالا است، پاها را آرام به سمت باسن جمع کنید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع صاف کنید.
۶. لگن را به زمین برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0696.gif', 'hamstring', 'gluteal,calves', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Bend your knees and place your feet flat on the ground, hip-width apart.
3. Lift your hips off the ground, engaging your glutes and hamstrings.
4. Slowly curl your legs towards your glutes, keeping your hips lifted.
5. Pause for a moment at the top, then slowly extend your legs back to the starting position.
6. Lower your hips back down to the ground.
7. Repeat for the desired number of repetitions.', '0696') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1763', 'بارفیکس دست به اندازه شانه', 'Shoulder grip pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. میله بارفیکس را به اندازه عرض شانه و کف دست رو به جلو بگیرید.
۲. با دست‌های کاملاً صاف آزادانه آویزان شوید.
۳. عضلات پشت را درگیر کنید و بدن را بالا بکشید تا چانه از میله بالاتر رود.
۴. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1763.gif', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with a shoulder-width grip, palms facing away from you.
2. Hang freely with your arms fully extended.
3. Engage your back muscles and pull your body up towards the bar until your chin is above the bar.
4. Pause for a moment at the top, then slowly lower your body back down to the starting position.
5. Repeat for the desired number of repetitions.', '1763') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3699', 'لمس شانه', 'Shoulder tap', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، پشت بازو', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها درست زیر شانه‌ها و بدن در یک خط صاف.
۲. میان‌تنه را درگیر کنید و دست راست را از زمین بلند کنید و به شانه چپ ضربه بزنید.
۳. دست راست را به زمین برگردانید و با دست چپ به شانه راست ضربه بزنید.
۴. با ثابت نگه داشتن لگن و تنه، ضربه به شانه‌ها را یکی در میان ادامه دهید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3699.gif', 'abs', 'deltoids,triceps', '1. Start in a high plank position with your hands directly under your shoulders and your body in a straight line.
2. Engage your core and lift your right hand off the ground, reaching across to tap your left shoulder.
3. Place your right hand back on the ground and repeat with your left hand tapping your right shoulder.
4. Continue alternating shoulder taps while keeping your hips and torso stable.
5. Repeat for the desired number of repetitions.', '3699') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0699', 'شنا سوئدی با لمس شانه', 'Shoulder tap push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، میان‌تنه', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها کمی بازتر از عرض شانه و بدن از سر تا پاشنه در یک خط صاف.
۲. با خم کردن آرنج‌ها بدن را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. هنگام بالا رفتن، دست راست را از زمین بلند کنید و به شانه چپ ضربه بزنید.
۴. دست راست را به زمین برگردانید و شنا را تکرار کنید، این بار با دست چپ به شانه راست ضربه بزنید.
۵. در هر تکرار شنا ضربه به شانه را یکی در میان ادامه دهید.
۶. در طول تمرین میان‌تنه را ثابت نگه دارید و از چرخش زیاد لگن خودداری کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0699.gif', 'chest', 'triceps,abs', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your body in a straight line from head to heels.
2. Lower your body towards the ground by bending your elbows, keeping them close to your sides.
3. As you push back up, lift your right hand off the ground and tap your left shoulder.
4. Return your right hand to the ground and repeat the push-up, this time lifting your left hand and tapping your right shoulder.
5. Continue alternating shoulder taps with each push-up repetition.
6. Maintain a stable core and avoid excessive hip rotation throughout the exercise.
7. Repeat for the desired number of repetitions.', '0699') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1774', 'پلانک پهلو با دور کردن ران', 'Side bridge hip abduction', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'دورکننده ران', 'سرینی (باسن)، پهلوها', '۱. به پهلو دراز بکشید و پاها را صاف و روی هم قرار دهید.
۲. روی ساعد تکیه دهید و آرنج را درست زیر شانه نگه دارید.
۳. میان‌تنه را درگیر کنید و لگن را از زمین بلند کنید تا بدن از سر تا پا یک خط صاف بسازد.
۴. با میان‌تنه درگیر، پای بالایی را بدون چرخاندن لگن تا جای ممکن بالا ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پا را پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1774.gif', 'gluteal', 'obliques', '1. Lie on your side with your legs extended and stacked on top of each other.
2. Prop yourself up on your forearm, keeping your elbow directly below your shoulder.
3. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.
4. While keeping your core engaged, lift your top leg as high as possible without rotating your hips.
5. Pause for a moment at the top, then lower your leg back down.
6. Repeat for the desired number of repetitions, then switch sides.', '1774') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0705', 'پلانک پهلو (نسخه ۲)', 'Side bridge v. 2', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، سرینی (باسن)', '۱. به پهلو دراز بکشید و پاها را صاف و روی هم قرار دهید.
۲. ساعد را درست زیر شانه روی زمین بگذارید و آرنج را ۹۰ درجه خم کنید.
۳. میان‌تنه را درگیر کنید و لگن را از زمین بلند کنید تا بدن از سر تا پا یک خط صاف بسازد.
۴. این وضعیت را برای مدت دلخواه نگه دارید.
۵. لگن را به وضعیت شروع پایین بیاورید.
۶. حرکت را برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0705.gif', 'abs', 'obliques,gluteal', '1. Lie on your side with your legs extended and stacked on top of each other.
2. Place your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.
3. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.
4. Hold this position for the desired amount of time.
5. Lower your hips back down to the starting position.
6. Repeat on the other side.', '0705') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0709', 'لگن جانبی (روی پارالل)', 'Side hip (on parallel bars)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، خم‌کننده ران', '۱. بین دو میله موازی بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دست‌ها را روی میله‌ها بگذارید و بدن را از زمین بلند کنید و وزن را روی دست‌ها نگه دارید.
۳. شکم را درگیر کنید و پاها را صاف و آرام به طرف بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0709.gif', 'abs', 'obliques,hip-flexors', '1. Stand between two parallel bars with your feet shoulder-width apart.
2. Place your hands on the bars and lift your body off the ground, supporting your weight on your arms.
3. Engage your abs and slowly lift your legs to the side, keeping them straight.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0709') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0710', 'دور کردن ران جانبی', 'Side hip abduction', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'دورکننده ران', 'سرینی (باسن)، چهارسر ران', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را روی لگن بگذارید.
۲. وزن را روی یک پا ببرید و پای دیگر را صاف به طرف بالا ببرید.
۳. لحظه‌ای در بالا مکث کنید، سپس پا را آرام به وضعیت شروع پایین بیاورید.
۴. حرکت را برای طرف دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0710.gif', 'gluteal', 'quadriceps', '1. Stand with your feet shoulder-width apart and your hands on your hips.
2. Shift your weight to one leg and lift the opposite leg out to the side, keeping it straight.
3. Pause for a moment at the top, then slowly lower your leg back down to the starting position.
4. Repeat on the other side.
5. Continue alternating sides for the desired number of repetitions.', '0710') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1358', 'کشش خوابیده به پهلو روی زمین', 'Side lying floor stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'پهلوها، سرینی (باسن)', '۱. به پهلو دراز بکشید، پاها صاف و دست زیرین صاف بالای سر باشد.
۲. زانوی بالایی را خم کنید و پا را جلوی پای زیرین روی زمین بگذارید.
۳. دست بالایی را از بالای سر ببرید و یک جسم ثابت مانند دیوار یا وسیله‌ای را بگیرید.
۴. پای زیرین را صاف و آرام از زمین بلند کنید تا کشش را در پهلو حس کنید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید، سپس پا را آرام پایین بیاورید.
۶. حرکت را برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1358.gif', 'upper-back', 'obliques,gluteal', '1. Lie on your side with your legs straight and your bottom arm extended straight overhead.
2. Bend your top knee and place your foot on the ground in front of your bottom leg.
3. Reach your top arm over your head and grab onto something stable, like a wall or a piece of furniture.
4. Slowly lift your bottom leg off the ground, keeping it straight, until you feel a stretch in your side.
5. Hold the stretch for 20-30 seconds, then slowly lower your leg back down.
6. Repeat on the other side.', '1358') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3667', 'نزدیک کردن ران خوابیده به پهلو', 'Side lying hip adduction (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'نزدیک‌کننده ران', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. به پهلو دراز بکشید و پاها را صاف و روی هم قرار دهید.
۲. برای حمایت دست زیرین را زیر سر بگذارید.
۳. عضلات نزدیک‌کننده را درگیر کنید و پای بالایی را بدون چرخاندن لگن یا خم شدن به عقب تا جای ممکن بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پا را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3667.gif', 'adductors', 'gluteal,hamstring', '1. Lie on your side with your legs straight and stacked on top of each other.
2. Place your bottom arm under your head for support.
3. Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.
4. Pause for a moment at the top, then slowly lower your leg back down to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '3667') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1775', 'پلانک پهلو با نزدیک کردن ران', 'Side plank hip adduction', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'نزدیک‌کننده ران', 'پهلوها، سرینی (باسن)', '۱. به پهلو دراز بکشید و پاها را صاف و روی هم قرار دهید.
۲. روی ساعد تکیه دهید و آرنج را درست زیر شانه نگه دارید.
۳. میان‌تنه را درگیر کنید و لگن را از زمین بلند کنید تا بدن از سر تا پا یک خط صاف بسازد.
۴. در حالت پلانک پهلو، پای بالایی را صاف به سمت سقف بالا ببرید.
۵. پا را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1775.gif', 'adductors', 'obliques,gluteal', '1. Start by lying on your side with your legs extended and stacked on top of each other.
2. Prop yourself up on your forearm, keeping your elbow directly below your shoulder.
3. Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.
4. While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.
5. Slowly lower your leg back down to the starting position.
6. Repeat for the desired number of repetitions, then switch sides.', '1775') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0717', 'شنا سوئدی جانبی', 'Side push-up', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'شانه‌ها، سینه، میان‌تنه', '۱. به پهلو دراز بکشید و پاها را صاف و روی هم قرار دهید.
۲. دست زیرین را درست زیر شانه روی زمین بگذارید، انگشتان رو به جلو.
۳. با فشار دست زیرین بدن را از زمین بلند کنید و پاها را صاف و میان‌تنه را درگیر نگه دارید.
۴. دست بالایی را صاف به سمت سقف ببرید تا بدن از سر تا پاشنه یک خط صاف بسازد.
۵. بدن را با کنترل به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0717.gif', 'triceps', 'deltoids,chest,abs', '1. Start by lying on your side with your legs extended and stacked on top of each other.
2. Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.
3. Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.
4. Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.
5. Lower your body back down to the starting position with control.
6. Repeat for the desired number of repetitions, then switch sides.', '0717') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0721', 'کشش جانبی مچ دست', 'Side wrist pull stretch', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'ساعد', 'مچ دست، دست‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را جلوی بدن دراز کنید.
۲. دست راست را به طرف و موازی زمین با کف دست رو به پایین باز کنید.
۳. با دست چپ دست راست را بگیرید و آرام به سمت بدن بکشید تا کشش را در ساعد راست حس کنید.
۴. کشش را ۱۵ تا ۳۰ ثانیه نگه دارید و سپس رها کنید.
۵. حرکت را برای طرف دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0721.gif', 'forearm', '', '1. Stand with your feet shoulder-width apart and your arms extended in front of you.
2. Extend your right arm out to the side, parallel to the ground, with your palm facing down.
3. With your left hand, grab your right hand and gently pull it towards your body, feeling a stretch in your right forearm.
4. Hold the stretch for 15-30 seconds, then release.
5. Repeat on the other side.', '0721') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0720', 'بارفیکس جانب به جانب', 'Side-to-side chin', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. میله بارفیکس را از رو و کمی بازتر از عرض شانه بگیرید.
۳. با دست‌های کاملاً صاف و بدن رها از میله آویزان شوید.
۴. با خم کردن آرنج‌ها خود را بالا بکشید و چانه را به میله نزدیک کنید و بدن را صاف نگه دارید.
۵. وقتی چانه از میله بالاتر رفت، به وضعیت شروع پایین بیایید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0720.gif', 'upper-back', 'biceps,forearm', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp a pull-up bar with an overhand grip, hands slightly wider than shoulder-width apart.
3. Hang from the bar with your arms fully extended and your body relaxed.
4. Pull yourself up by bending your elbows and bringing your chin towards the bar, while keeping your body straight.
5. Once your chin is above the bar, lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '0720') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3213', 'لمس پنجه پا جانب به جانب', 'Side-to-side toe touch (male)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، خم‌کننده ران', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را به طرفین باز کنید.
۲. از کمر به راست خم شوید و دست راست را به سمت پای راست ببرید و دست چپ را به طرف باز نگه دارید.
۳. به وضعیت شروع برگردید و سپس به چپ خم شوید و دست چپ را به سمت پای چپ ببرید و دست راست را باز نگه دارید.
۴. حرکت خم شدن به طرفین را به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3213.gif', 'abs', 'obliques,hip-flexors', '1. Stand with your feet shoulder-width apart and your arms extended to the sides.
2. Bend at the waist to the right, reaching your right hand towards your right foot while keeping your left hand extended to the side.
3. Return to the starting position and then bend at the waist to the left, reaching your left hand towards your left foot while keeping your right hand extended to the side.
4. Repeat the side-to-side bending motion for the desired number of repetitions.', '3213') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0725', 'شنا سوئدی تک‌دست', 'Single arm push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها، میان‌تنه', '۱. در وضعیت شنا قرار بگیرید، دست‌ها به اندازه عرض شانه و یک دست کمی بازتر از دیگری باشد.
۲. میان‌تنه را درگیر کنید و با خم کردن آرنج‌ها بدن را به سمت زمین پایین ببرید و کمر را صاف نگه دارید.
۳. هنگام پایین رفتن، وزن را به یک طرف ببرید و دست مخالف را از زمین بلند کنید و صاف به طرف باز کنید.
۴. با کمک سینه و پشت بازو بدن را به وضعیت شروع بالا ببرید و همزمان دست باز را به زمین برگردانید.
۵. حرکت را تکرار کنید و در هر تکرار دست باز را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0725.gif', 'chest', 'triceps,deltoids,abs', '1. Start in a push-up position with your hands shoulder-width apart and one hand placed slightly wider than the other.
2. Engage your core and lower your body towards the ground by bending your elbows, keeping your back straight.
3. As you lower yourself, shift your weight to one side and lift the opposite arm off the ground, extending it straight out to the side.
4. Push through your chest and triceps to raise your body back up to the starting position, while simultaneously lowering your extended arm back to the ground.
5. Repeat the movement, alternating the arm you extend with each repetition.', '0725') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3645', 'پل تک‌پا با پای کشیده', 'Single leg bridge with outstretched leg', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران', '۱. به پشت دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. یک پا را صاف جلوی بدن دراز کنید.
۳. باسن را درگیر کنید و لگن را از زمین بلند کنید تا بدن از زانو تا شانه یک خط صاف بسازد.
۴. لحظه‌ای در بالا نگه دارید، سپس لگن را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3645.gif', 'gluteal', 'hamstring,quadriceps', '1. Lie on your back with your knees bent and feet flat on the ground.
2. Extend one leg straight out in front of you.
3. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.
4. Hold for a moment at the top, then slowly lower your hips back down to the starting position.
5. Repeat for the desired number of repetitions, then switch legs.', '3645') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0727', 'ساق پا تک‌پا (روی دمبل)', 'Single leg calf raise (on a dumbbell)', 'legs', 'پا', 'dumbbell', 'دمبل', 'ساق پا', 'مچ پا، پاها', '۱. بایستید، پاها را به اندازه عرض لگن باز کنید و یک دمبل در یک دست بگیرید.
۲. یک پا را از زمین بلند کنید و روی پای دیگر تعادل بگیرید.
۳. با کمک عضلات ساق، پاشنه را آرام تا جای ممکن بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه را آرام پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0727.gif', 'calves', '', '1. Stand with your feet hip-width apart and hold a dumbbell in one hand.
2. Lift one foot off the ground and balance on the other foot.
3. Slowly raise your heel as high as possible, using your calf muscles.
4. Pause for a moment at the top, then slowly lower your heel back down.
5. Repeat for the desired number of repetitions, then switch to the other leg.', '0727') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0730', 'لغزش تک‌پا روی سکو', 'Single leg platform slide', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)، چهارسر ران', '۱. با یک پا روی سکو یا تخته لغزان بایستید.
۲. زانو را کمی خم کنید و پای روی سکو را به عقب بلغزانید و پا را باز کنید.
۳. در طول حرکت میان‌تنه را درگیر و بدن را صاف نگه دارید.
۴. با برگرداندن پا به جای اول، آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0730.gif', 'hamstring', 'gluteal,quadriceps', '1. Start by standing with one foot on a platform or slide board.
2. Bend your knee slightly and slide the foot on the platform backward, extending your leg.
3. Keep your core engaged and maintain a straight posture throughout the movement.
4. Slowly return to the starting position by sliding your foot back to the initial position.
5. Repeat the movement for the desired number of repetitions, then switch legs.', '0730') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1759', 'اسکوات تک‌پا (پیستول)', 'Single leg squat (pistol) male', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را جلوی بدن دراز کنید.
۲. پای راست را از زمین بلند کنید و به جلو دراز کنید.
۳. با خم کردن زانوی چپ و بردن لگن به عقب بدن را آرام پایین ببرید.
۴. هنگام پایین رفتن سینه را بالا و کمر را صاف نگه دارید.
۵. تا جایی پایین بروید که ران چپ موازی زمین شود یا تا جایی که راحت هستید.
۶. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه چپ به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1759.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart and arms extended in front of you.
2. Lift your right foot off the ground and extend it forward.
3. Slowly lower your body down by bending your left knee and pushing your hips back.
4. Keep your chest up and your back straight as you lower yourself down.
5. Lower until your left thigh is parallel to the ground, or as low as you can comfortably go.
6. Pause for a moment at the bottom, then push through your left heel to return to the starting position.
7. Repeat for the desired number of repetitions, then switch legs.', '1759') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1489', 'سیسی اسکوات', 'Sissy squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'ساق پا، سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. در صورت نیاز برای حفظ تعادل یک جسم ثابت را بگیرید.
۳. با خم کردن زانوها و متمایل شدن به عقب بدن را آرام پایین ببرید و تنه را صاف نگه دارید.
۴. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۵. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1489.gif', 'quadriceps', 'calves,gluteal', '1. Stand with your feet shoulder-width apart and your toes pointing slightly outward.
2. Hold onto a stable object for balance if needed.
3. Slowly lower your body by bending your knees and leaning back, keeping your torso upright.
4. Continue lowering until your thighs are parallel to the ground or as far as you can comfortably go.
5. Pause for a moment, then push through your heels to return to the starting position.
6. Repeat for the desired number of repetitions.', '1489') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0735', 'دراز و نشست (نسخه ۲)', 'Sit-up v. 2', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن عضلات شکم، بالاتنه را آرام از زمین بلند کنید و به جلو خم شوید تا تنه زاویه ۴۵ درجه بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0735.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly lift your upper body off the ground, curling forward until your torso is at a 45-degree angle.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0735') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3679', 'دراز و نشست با دست‌ها روی سینه', 'Sit-up with arms on chest', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را روی سینه ضربدری کنید.
۳. با درگیر کردن شکم، بالاتنه را از زمین به سمت زانوها بلند کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3679.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Cross your arms over your chest.
3. Engaging your abs, lift your upper body off the ground towards your knees.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3679') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2142', 'اسکی ارگومتر', 'Ski ergometer', 'arms', 'بازو', 'other', 'سایر', 'پشت بازو', 'شانه‌ها، ساعد', '۱. ارتفاع صندلی و جاپایی را در وضعیت مناسب تنظیم کنید.
۲. دستگیره‌ها را از رو با کف دست رو به پایین بگیرید.
۳. صاف بنشینید و کف پاها را روی جاپایی بگذارید.
۴. دست‌ها را صاف جلوی بدن دراز کنید و آرنج‌ها را کمی خم نگه دارید.
۵. پشت بازو را درگیر کنید و دستگیره‌ها را به سمت ران‌ها پایین فشار دهید.
۶. لحظه‌ای در پایین مکث کنید، سپس آرام به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2142.gif', 'triceps', 'deltoids,forearm', '1. Adjust the seat height and footrests to a comfortable position.
2. Grasp the handles with an overhand grip, palms facing down.
3. Sit up straight with your feet flat on the footrests.
4. Extend your arms straight out in front of you, keeping your elbows slightly bent.
5. Engage your triceps and push the handles down towards your thighs.
6. Pause for a moment at the bottom, then slowly return to the starting position.
7. Repeat for the desired number of repetitions.', '2142') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3304', 'اسکین د کت', 'Skin the cat', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'شانه‌ها، میان‌تنه', '۱. از یک میله با دست‌های کاملاً صاف و بدن رها آویزان شوید.
۲. میان‌تنه را درگیر کنید و پاها را بالا بیاورید و زانوها را به سمت سینه ببرید.
۳. پاها را بالا و از روی سر ببرید و اجازه دهید بدن از بین دست‌ها عبور کند.
۴. وقتی پاها کاملاً بالای سر صاف شدند، شروع به پایین آوردن آن‌ها به سمت وضعیت شروع کنید.
۵. هنگام پایین آوردن پاها، اجازه دهید بدن دوباره از بین دست‌ها عبور کند تا دوباره با دست‌های صاف آویزان شوید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3304.gif', 'upper-back', 'deltoids,abs', '1. Start by hanging from a bar with your arms fully extended and your body relaxed.
2. Engage your core and lift your legs up, bringing your knees towards your chest.
3. Continue to lift your legs up and over your head, allowing your body to pass through the arms.
4. Once your legs are fully extended over your head, begin to lower them back down towards the starting position.
5. As you lower your legs, allow your body to pass back through the arms until you are hanging with your arms fully extended again.
6. Repeat for the desired number of repetitions.', '3304') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1425', 'پرس پا تک‌پا ۴۵ درجه', 'Sled 45 degrees one leg press', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. دستگاه را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پد و پاها روی سکو باشد.
۳. یک پا را روی سکو بگذارید و پا را باز کنید تا سکو از شما دور شود.
۴. زانو را آرام خم کنید و سکو را به وضعیت شروع برگردانید.
۵. با پای دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه، پاها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1425.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a 45-degree angle.
2. Sit on the sled machine with your back against the pad and your feet on the footplate.
3. Place one foot on the footplate and extend your leg, pushing the sled away from you.
4. Slowly bend your knee and lower the sled back to the starting position.
5. Repeat with the other leg.
6. Continue alternating legs for the desired number of repetitions.', '1425') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0738', 'ساق پا پرسی ۴۵ درجه', 'Sled 45° calf press', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)', '۱. دستگاه را روی زاویه ۴۵ درجه تنظیم کنید.
۲. پاها را روی سکوی دستگاه با پنجه‌های رو به جلو بگذارید.
۳. با باز کردن مچ پا و ساق، سکو را از خود دور کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس سکو را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0738.gif', 'calves', 'hamstring', '1. Adjust the sled machine to a 45-degree angle.
2. Place your feet on the sled platform with your toes pointing forward.
3. Push the sled platform away from you by extending your ankles and calves.
4. Pause for a moment at the top, then slowly lower the sled platform back to the starting position.
5. Repeat for the desired number of repetitions.', '0738') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1464', 'پرس پا ۴۵ درجه (نمای پشت)', 'Sled 45° leg press (back pov)', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. صندلی دستگاه را طوری تنظیم کنید که زانوها ۴۵ درجه باشند.
۲. روی دستگاه بنشینید، کمر به پشتی و پاها به اندازه عرض شانه روی سکو باشد.
۳. برای ثبات دستگیره‌های کنار صندلی را بگیرید.
۴. با باز کردن پاها سکو را از بدن دور کنید و پاشنه‌ها را روی سکو نگه دارید.
۵. لحظه‌ای در حالت کاملاً باز مکث کنید.
۶. زانوها را آرام خم کنید و سکو را با کنترل به سمت بدن برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1464.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the seat of the sled machine so that your knees are at a 45-degree angle.
2. Sit on the sled machine with your back against the backrest and your feet shoulder-width apart on the footplate.
3. Grip the handles on the sides of the seat for stability.
4. Push the footplate away from your body by extending your legs, keeping your heels on the footplate.
5. Pause for a moment at the fully extended position.
6. Slowly bend your knees and lower the footplate back towards your body, controlling the movement.
7. Repeat for the desired number of repetitions.', '1464') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1463', 'پرس پا ۴۵ درجه (نمای جانبی)', 'Sled 45° leg press (side pov)', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. صندلی دستگاه را طوری تنظیم کنید که وقتی پاها روی سکو هستند زانوها ۹۰ درجه باشند.
۲. روی دستگاه بنشینید، کمر صاف به پشتی و پاها به اندازه عرض شانه روی سکو باشد.
۳. برای ثبات دستگیره‌های کنار صندلی را بگیرید.
۴. به سکو فشار دهید تا پاها کاملاً صاف شوند.
۵. لحظه‌ای در بالا مکث کنید، سپس زانوها را آرام خم کنید و سکو را به وضعیت شروع برگردانید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1463.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.
2. Sit on the sled machine with your back flat against the backrest and your feet shoulder-width apart on the footplate.
3. Grip the handles on the sides of the seat for stability.
4. Push against the footplate to extend your legs, straightening them completely.
5. Pause for a moment at the top, then slowly bend your knees to lower the footplate back to the starting position.
6. Repeat for the desired number of repetitions.', '1463') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0740', 'پرس پا ۴۵ درجه با پای باز', 'Sled 45° leg wide press', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. دستگاه را روی زاویه ۴۵ درجه تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پد و پاها روی سکو باشد.
۳. پاها را بازتر از عرض شانه قرار دهید.
۴. به سکو فشار دهید تا پاها باز و زانوها صاف شوند.
۵. لحظه‌ای در انتهای حرکت مکث کنید، سپس زانوها را آرام خم کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0740.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a 45-degree angle.
2. Sit on the sled machine with your back against the pad and your feet on the foot platform.
3. Position your feet wider than shoulder-width apart.
4. Push against the foot platform to extend your legs and straighten your knees.
5. Pause for a moment at the end of the movement, then slowly bend your knees to return to the starting position.
6. Repeat for the desired number of repetitions.', '0740') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1391', 'ساق پا روی دستگاه پرس پا', 'Sled calf press on leg press', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، چهارسر ران', '۱. صندلی دستگاه پرس پا را طوری تنظیم کنید که وقتی پاها روی سکو هستند زانوها کمی خم باشند.
۲. پاها را به اندازه عرض شانه با پنجه‌های رو به جلو روی سکو بگذارید.
۳. دستگیره‌های ایمنی را آزاد کنید و با باز کردن زانوها و مچ پاها سکو را از خود دور کنید.
۴. لحظه‌ای در اوج حرکت مکث کنید، سپس با خم کردن زانوها و مچ پاها سکو را آرام پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1391.gif', 'calves', 'hamstring,quadriceps', '1. Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.
2. Place your feet shoulder-width apart on the sled, with your toes pointing forward.
3. Release the safety handles and push the sled away from you by extending your knees and ankles.
4. Pause for a moment at the top of the movement, then slowly lower the sled back down by bending your knees and ankles.
5. Repeat for the desired number of repetitions.', '1391') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0741', 'هاک اسکوات پا جمع دستگاه', 'Sled closer hack squat', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. دستگاه را روی وزن مناسب تنظیم کنید و با کمر به پد قرار بگیرید.
۲. پاها را به اندازه عرض شانه با پنجه‌های کمی رو به بیرون روی سکو بگذارید.
۳. برای ثبات دستگیره‌های کنار دستگاه را بگیرید.
۴. میان‌تنه را درگیر کنید و با خم کردن زانوها و لگن آرام پایین بروید و کمر را صاف نگه دارید.
۵. تا جایی پایین بروید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۶. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها پاها را صاف کنید و به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0741.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a comfortable weight and position yourself with your back against the pad.
2. Place your feet shoulder-width apart on the platform, toes slightly pointed outwards.
3. Grip the handles on the sides of the machine for stability.
4. Engage your core and slowly lower your body by bending your knees and hips, keeping your back straight.
5. Continue lowering until your thighs are parallel to the ground or slightly below.
6. Pause for a moment at the bottom, then push through your heels to extend your legs and return to the starting position.
7. Repeat for the desired number of repetitions.', '0741') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0742', 'ساق پا زاویه‌دار رو به جلو دستگاه', 'Sled forward angled calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. دستگاه را روی وزن مناسب تنظیم کنید و با پنجه‌ها روی سکو و پاشنه‌های آزاد قرار بگیرید.
۲. برای حمایت دست‌ها را روی دستگیره‌ها یا کناره‌های دستگاه بگذارید.
۳. ساق‌ها را درگیر کنید و پاشنه‌ها را در برابر مقاومت دستگاه آرام تا جای ممکن بالا ببرید.
۴. لحظه‌ای در اوج حرکت مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0742.gif', 'calves', 'hamstring,gluteal', '1. Adjust the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.
2. Place your hands on the handles or the sides of the machine for support.
3. Engage your calves and slowly raise your heels as high as possible, pushing against the resistance of the sled.
4. Pause for a moment at the top of the movement, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '0742') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0743', 'هاک اسکوات دستگاه', 'Sled hack squat', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. دستگاه را متناسب با قد خود تنظیم کنید.
۲. پاها را به اندازه عرض شانه با پنجه‌های کمی رو به بیرون روی سکو بگذارید.
۳. برای ثبات دستگیره‌ها یا میله‌ها را بگیرید.
۴. با خم کردن زانوها و لگن بدن را پایین ببرید و کمر را صاف و سینه را بالا نگه دارید.
۵. تا جایی پایین بروید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۶. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع بالا بروید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0743.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a comfortable position for your height.
2. Stand with your feet shoulder-width apart on the platform, toes slightly pointed outwards.
3. Hold onto the handles or bars for stability.
4. Lower your body by bending your knees and hips, keeping your back straight and chest up.
5. Continue lowering until your thighs are parallel to the ground or slightly below.
6. Pause for a moment, then push through your heels to raise your body back up to the starting position.
7. Repeat for the desired number of repetitions.', '0743') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2334', 'ساق پا پرسی خوابیده دستگاه', 'Sled lying calf press', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. دستگاه را روی وزن مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پد و پاها روی سکو باشد.
۳. پنجه‌ها و جلوی کف پا را روی لبه سکو بگذارید و پاشنه‌ها آزاد باشند.
۴. با باز کردن مچ پا سکو را از خود دور کنید و زانوها را کمی خم نگه دارید.
۵. تا جایی فشار دهید که ساق‌ها کاملاً منقبض شوند.
۶. انقباض را لحظه‌ای نگه دارید، سپس سکو را آرام به وضعیت شروع برگردانید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2334.gif', 'calves', 'hamstring,gluteal', '1. Adjust the sled machine to a comfortable weight.
2. Sit on the sled machine with your back against the pad and your feet on the platform.
3. Place your toes and the balls of your feet on the edge of the platform, with your heels hanging off.
4. Push the platform away from you by extending your ankles, keeping your knees slightly bent.
5. Continue pushing until your calves are fully contracted.
6. Hold the contraction for a moment, then slowly lower the platform back to the starting position.
7. Repeat for the desired number of repetitions.', '2334') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0744', 'اسکوات خوابیده دستگاه', 'Sled lying squat', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. دستگاه را روی وزن مناسب تنظیم کنید.
۲. روی دستگاه به پشت دراز بکشید و پاها را روی سکو بگذارید.
۳. پاها را به اندازه عرض شانه و کمی رو به بیرون قرار دهید.
۴. برای ثبات دستگیره‌های دستگاه را بگیرید.
۵. عضلات باسن و میان‌تنه را درگیر کنید.
۶. با فشار پاشنه‌ها و باز کردن پاها سکو را بالا ببرید.
۷. با خم کردن زانوها و لگن سکو را پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0744.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the sled machine to a comfortable weight.
2. Lie on your back on the sled machine with your feet on the footplate.
3. Position your feet shoulder-width apart and slightly angled outwards.
4. Grip the handles of the sled machine for stability.
5. Engage your glutes and core muscles.
6. Push through your heels and extend your legs to lift the sled.
7. Lower the sled back down by bending your knees and hips.
8. Repeat for the desired number of repetitions.', '0744') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1392', 'ساق پا تک‌پا روی دستگاه پرس پا', 'Sled one leg calf press on leg press', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. صندلی دستگاه پرس پا را طوری تنظیم کنید که وقتی پاها روی سکو هستند زانوها کمی خم باشند.
۲. روی دستگاه بنشینید، کمر به پشتی و پاها به اندازه عرض شانه روی سکو باشد.
۳. پنجه‌ها و جلوی کف پا را روی سکو بگذارید و پاشنه‌ها آزاد باشند.
۴. با باز کردن مچ پا سکو را به جلو هل دهید و زانوها را کمی خم نگه دارید.
۵. لحظه‌ای در بالا مکث کنید، سپس با خم کردن مچ پا سکو را آرام پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1392.gif', 'calves', 'hamstring,gluteal', '1. Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the sled.
2. Sit on the machine with your back against the backrest and your feet on the sled, shoulder-width apart.
3. Place your toes and the balls of your feet on the sled, keeping your heels off.
4. Push the sled forward by extending your ankles, keeping your knees slightly bent.
5. Pause for a moment at the top, then slowly lower the sled back down by flexing your ankles.
6. Repeat for the desired number of repetitions.', '1392') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1496', 'پتک', 'Sledge hammer', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'ساعد، شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پتک را با دو دست بگیرید.
۲. میان‌تنه را درگیر و کمر را صاف نگه دارید.
۳. با قدرت میان‌تنه و بالاتنه پتک را به سمت زمین پایین بیاورید.
۴. هنگام پایین آوردن، لگن را بچرخانید و نیرو را به پتک منتقل کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1496.gif', 'abs', 'forearm,deltoids', '1. Stand with your feet shoulder-width apart and hold the sledge hammer with both hands.
2. Engage your core and keep your back straight.
3. Swing the sledge hammer down towards the ground, using your core and upper body strength.
4. As you swing down, pivot your hips and transfer the force to the hammer.
5. Repeat for the desired number of repetitions.', '1496') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0746', 'شراگ از پشت اسمیت', 'Smith back shrug', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'کول (ذوزنقه)', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. دست‌ها را صاف نگه دارید و اجازه دهید هالتر جلوی ران‌ها آویزان باشد.
۴. شانه‌ها را مستقیم به سمت گوش‌ها بالا ببرید و در بالا عضلات کول را منقبض کنید.
۵. لحظه‌ای نگه دارید، سپس شانه‌ها را به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0746.gif', 'trapezius', 'deltoids', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Keep your arms straight and allow the barbell to hang in front of your thighs.
4. Lift your shoulders straight up towards your ears, squeezing your traps at the top.
5. Hold for a moment, then lower your shoulders back down to the starting position.
6. Repeat for the desired number of repetitions.', '0746') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0747', 'پرس پشت گردن اسمیت', 'Smith behind neck press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، بالای پشت', '۱. ارتفاع دستگاه اسمیت را طوری تنظیم کنید که میله در سطح شانه باشد.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۳. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. میله را از جایگاه بردارید و یک قدم عقب بروید و وضعیت ثابتی بگیرید.
۵. میله را تا پشت گردن پایین بیاورید و آرنج‌ها را رو به جلو نگه دارید.
۶. میله را بالای سر پرس کنید تا دست‌ها کاملاً صاف شوند.
۷. لحظه‌ای در بالا مکث کنید، سپس میله را آرام به وضعیت شروع پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0747.gif', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height of the smith machine so that the bar is at shoulder level.
2. Stand with your feet shoulder-width apart and your knees slightly bent.
3. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
4. Lift the bar off the rack and step back, maintaining a stable stance.
5. Lower the bar down to the back of your neck, keeping your elbows pointing forward.
6. Press the bar up overhead until your arms are fully extended.
7. Pause for a moment at the top, then slowly lower the bar back down to the starting position.
8. Repeat for the desired number of repetitions.', '0747') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0748', 'پرس سینه اسمیت', 'Smith bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. ارتفاع میله اسمیت را در سطح سینه تنظیم کنید.
۲. روی نیمکت صاف دراز بکشید و پاها را محکم روی زمین بگذارید.
۳. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. میله را از جایگاه بردارید و به سمت سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۵. وقتی میله به سینه رسید لحظه‌ای مکث کنید.
۶. میله را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0748.gif', 'chest', 'triceps,deltoids', '1. Adjust the height of the smith machine bar to chest level.
2. Lie flat on the bench with your feet firmly planted on the ground.
3. Grip the bar with an overhand grip slightly wider than shoulder-width apart.
4. Unrack the bar and lower it towards your chest, keeping your elbows tucked in.
5. Pause for a moment when the bar touches your chest.
6. Push the bar back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '0748') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0749', 'گودمورنینگ زانو خم اسمیت', 'Smith bent knee good morning', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'همسترینگ (پشت ران)، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها رو به جلو باشد.
۲. هالتر را روی بالای کمر و روی عضلات کول قرار دهید.
۳. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۴. تنه را پایین ببرید تا موازی زمین شود و کشش را در همسترینگ حس کنید.
۵. با درگیر کردن باسن و همسترینگ تنه را به وضعیت شروع بالا بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0749.gif', 'gluteal', 'hamstring,lower-back', '1. Start by standing with your feet shoulder-width apart, toes pointing forward.
2. Place the barbell across your upper back, resting it on your traps.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Lower your torso until it is parallel to the ground, feeling a stretch in your hamstrings.
5. Engage your glutes and hamstrings to raise your torso back up to the starting position.
6. Repeat for the desired number of repetitions.', '0749') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1359', 'زیربغل خم اسمیت', 'Smith bent over row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، ساعد', '۱. دستگاه اسمیت را با میله در ارتفاع لگن تنظیم کنید.
۲. رو به میله بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۴. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۵. میله را به سمت پایین سینه بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس میله را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1359.gif', 'upper-back', 'biceps,forearm', '1. Set up the smith machine with the bar at hip height.
2. Stand facing the bar with your feet shoulder-width apart.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.
5. Pull the bar towards your lower chest, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower the bar back down to the starting position.
7. Repeat for the desired number of repetitions.', '1359') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0750', 'اسکوات صندلی اسمیت', 'Smith chair squat', 'legs', 'پا', 'machine', 'دستگاه', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. ارتفاع میله اسمیت را در وضعیت مناسب تنظیم کنید.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۳. هالتر را روی بالای کمر و روی عضلات کول قرار دهید.
۴. میان‌تنه را درگیر و سینه را بالا نگه دارید و با خم کردن زانوها و لگن آرام پایین بروید.
۵. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۶. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0750.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Adjust the height of the smith machine bar to a comfortable position.
2. Stand with your feet shoulder-width apart, toes slightly turned out.
3. Place the barbell across your upper back, resting it on your traps.
4. Engage your core and keep your chest up as you slowly lower your body by bending your knees and hips.
5. Continue lowering until your thighs are parallel to the ground, or as low as you can comfortably go.
6. Pause for a moment, then push through your heels to return to the starting position.
7. Repeat for the desired number of repetitions.', '0750') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0751', 'پرس سینه دست جمع اسمیت', 'Smith close-grip bench press', 'arms', 'بازو', 'machine', 'دستگاه', 'پشت بازو', 'سینه، شانه‌ها', '۱. ارتفاع صندلی را تنظیم کنید و روی نیمکت با کف پاها روی زمین قرار بگیرید.
۲. هالتر را با دست‌های جمع، کمی جمع‌تر از عرض شانه بگیرید.
۳. هالتر را به سمت سینه پایین بیاورید و آرنج‌ها را نزدیک بدن نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0751.gif', 'triceps', 'chest,deltoids', '1. Adjust the seat height and position yourself on the bench with your feet flat on the ground.
2. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
3. Lower the barbell towards your chest, keeping your elbows close to your body.
4. Pause for a moment at the bottom, then push the barbell back up to the starting position.
5. Repeat for the desired number of repetitions.', '0751') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0752', 'ددلیفت اسمیت', 'Smith deadlift', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، پایین کمر', '۱. دستگاه اسمیت را با میله در ارتفاع لگن تنظیم کنید.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۳. از لگن و زانوها خم شوید، کمر را صاف و سینه را بالا نگه دارید و میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. میان‌تنه را درگیر کنید و با باز کردن لگن و زانوها میله را بلند کنید و نزدیک بدن نگه دارید.
۵. صاف بایستید و لگن و زانوها را کاملاً باز کنید.
۶. با خم کردن لگن و زانوها میله را با کنترل و کمر صاف پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0752.gif', 'gluteal', 'hamstring,quadriceps,lower-back', '1. Set up the smith machine with the bar at hip height.
2. Stand with your feet shoulder-width apart, toes pointing slightly outward.
3. Bend at the hips and knees, keeping your back straight and chest up, and grip the bar with an overhand grip slightly wider than shoulder-width apart.
4. Engage your core and lift the bar by extending your hips and knees, keeping the bar close to your body.
5. Stand up straight, fully extending your hips and knees.
6. Lower the bar back down by bending at the hips and knees, maintaining control and keeping your back straight.
7. Repeat for the desired number of repetitions.', '0752') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0753', 'پرس زیرسینه اسمیت', 'Smith decline bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. نیمکت زیرسینه را روی زاویه دلخواه تنظیم کنید.
۲. روی نیمکت دراز بکشید و پاها را زیر پدهای پا محکم کنید.
۳. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۵. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0753.gif', 'chest', 'triceps,deltoids', '1. Adjust the decline bench to the desired angle.
2. Lie down on the bench with your feet secured under the foot pads.
3. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.
5. Pause for a moment at the bottom, then push the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '0753') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0754', 'پرس زیرسینه دست‌برعکس اسمیت', 'Smith decline reverse-grip press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. دستگاه اسمیت را برای حالت زیرسینه تنظیم کنید.
۲. روی نیمکت دراز بکشید و پاها را زیر پدهای پا محکم کنید.
۳. هالتر را دست‌برعکس و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و به سمت سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۵. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0754.gif', 'chest', 'triceps,deltoids', '1. Adjust the smith machine to a decline position.
2. Lie down on the bench with your feet secured under the foot pads.
3. Grasp the barbell with a reverse grip, hands slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it towards your chest, keeping your elbows tucked in.
5. Pause for a moment at the bottom, then push the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '0754') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1433', 'اسکوات از جلو اسمیت (گرفتن کلین)', 'Smith front squat (clean grip)', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. دستگاه اسمیت را با هالتر در ارتفاع شانه تنظیم کنید.
۲. رو به هالتر بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۴. یک قدم عقب بروید و هالتر را روی جلوی شانه‌ها، روی ترقوه و دلتوئیدها قرار دهید.
۵. سینه را بالا، کمر را صاف و میان‌تنه را درگیر نگه دارید.
۶. با خم کردن زانوها و لگن، مانند نشستن روی صندلی، بدن را پایین ببرید.
۷. تا جایی پایین بروید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۸. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۹. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1433.gif', 'gluteal', 'quadriceps,hamstring,calves,abs', '1. Set up the smith machine with the barbell at shoulder height.
2. Stand facing the barbell with your feet shoulder-width apart.
3. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
4. Step back and position the barbell on your front shoulders, resting it on your collarbone and deltoids.
5. Keep your chest up, back straight, and core engaged.
6. Lower your body by bending at the knees and hips, as if sitting back into a chair.
7. Continue lowering until your thighs are parallel to the ground or slightly below.
8. Pause for a moment, then push through your heels to return to the starting position.
9. Repeat for the desired number of repetitions.', '1433') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3281', 'اسکوات کامل اسمیت', 'Smith full squat', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. دستگاه اسمیت را با هالتر در ارتفاع شانه تنظیم کنید.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۳. زیر میله بروید و آن را روی بالای کمر و روی عضلات کول قرار دهید.
۴. میله را با دست‌ها کمی بازتر از عرض شانه بگیرید.
۵. میله را از جایگاه بردارید و یک قدم عقب بروید و وضعیت ثابتی بگیرید.
۶. سینه را بالا و میان‌تنه را درگیر نگه دارید و اسکوات را با بردن لگن به عقب و خم کردن زانوها شروع کنید.
۷. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که انعطاف اجازه می‌دهد.
۸. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۹. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3281.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at shoulder height.
2. Stand with your feet shoulder-width apart, toes slightly turned out.
3. Step under the bar and position it across your upper back, resting on your traps.
4. Grip the bar with your hands slightly wider than shoulder-width apart.
5. Unrack the bar and take a step back, maintaining a stable stance.
6. Keeping your chest up and core engaged, initiate the squat by pushing your hips back and bending your knees.
7. Lower your body until your thighs are parallel to the ground, or as low as your flexibility allows.
8. Pause for a moment at the bottom, then drive through your heels to return to the starting position.
9. Repeat for the desired number of repetitions.', '3281') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0755', 'هاک اسکوات اسمیت', 'Smith hack squat', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. هالتر دستگاه اسمیت را در ارتفاع مناسب بدن خود تنظیم کنید.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۳. زیر هالتر قرار بگیرید و آن را روی بالای کول و شانه‌ها قرار دهید.
۴. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۵. میان‌تنه را درگیر و سینه را بالا نگه دارید و هالتر را از جایگاه بردارید.
۶. یک قدم عقب بروید و پاها را کمی بازتر از عرض شانه قرار دهید.
۷. زانوها را خم کنید و بدن را پایین ببرید و سینه را بالا و کمر را صاف نگه دارید.
۸. تا جایی پایین بروید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۹. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۱۰. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0755.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the barbell on the smith machine to an appropriate height for your body.
2. Stand with your feet shoulder-width apart, toes slightly pointed outwards.
3. Position yourself under the barbell, resting it on your upper traps and shoulders.
4. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
5. Engage your core and keep your chest up as you unrack the barbell.
6. Take a step back and position your feet slightly wider than shoulder-width apart.
7. Bend your knees and lower your body down, keeping your chest up and back straight.
8. Continue descending until your thighs are parallel to the ground or slightly below.
9. Pause for a moment at the bottom, then push through your heels to return to the starting position.
10. Repeat for the desired number of repetitions.', '0755') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0756', 'بالا آوردن لگن اسمیت', 'Smith hip raise', 'core', 'شکم و میان‌تنه', 'machine', 'دستگاه', 'شکم', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. روی دستگاه اسمیت با کمر به پد و پاها به اندازه عرض شانه قرار بگیرید.
۲. دست‌ها را کمی بازتر از عرض شانه روی هالتر بگذارید.
۳. میان‌تنه و باسن را درگیر کنید و با فشار پاشنه‌ها لگن را از زمین بلند کنید.
۴. تا جایی بالا ببرید که بدن از زانو تا شانه یک خط صاف بسازد.
۵. لحظه‌ای در بالا نگه دارید، سپس لگن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0756.gif', 'abs', 'gluteal,hamstring', '1. Position yourself on the smith machine with your back against the pad and your feet shoulder-width apart.
2. Place your hands on the barbell, slightly wider than shoulder-width apart.
3. Engage your core and glutes, then push through your heels to raise your hips off the ground.
4. Continue lifting until your body forms a straight line from your knees to your shoulders.
5. Hold for a moment at the top, then slowly lower your hips back down to the starting position.
6. Repeat for the desired number of repetitions.', '0756') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0757', 'پرس بالاسینه اسمیت', 'Smith incline bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'شانه‌ها، پشت بازو', '۱. نیمکت را روی شیب ۳۰ تا ۴۵ درجه تنظیم کنید.
۲. روی نیمکت بنشینید، کمر صاف به پد و پاها محکم روی زمین باشد.
۳. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و آرام به سمت بالای سینه پایین بیاورید و آرنج‌ها را کمی جمع نگه دارید.
۵. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0757.gif', 'chest', 'deltoids,triceps', '1. Adjust the bench to a 30-45 degree incline.
2. Sit on the bench with your back flat against the pad and feet firmly on the ground.
3. Grasp the barbell with an overhand grip slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your upper chest, keeping your elbows slightly tucked in.
5. Pause for a moment at the bottom, then push the barbell back up to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '0757') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0758', 'پرس بالاسینه دست‌برعکس اسمیت', 'Smith incline reverse-grip press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. صندلی دستگاه اسمیت را روی زاویه شیب مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پد و کف پاها روی زمین باشد.
۳. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. میله را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۵. وقتی میله کمی بالاتر از سینه قرار گرفت لحظه‌ای مکث کنید.
۶. میله را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0758.gif', 'chest', 'triceps,deltoids', '1. Adjust the seat of the smith machine to a comfortable incline angle.
2. Sit on the machine with your back against the pad and your feet flat on the ground.
3. Grasp the bar with an overhand grip that is slightly wider than shoulder-width apart.
4. Unrack the bar and lower it slowly towards your chest, keeping your elbows tucked in.
5. Pause for a moment when the bar is just above your chest.
6. Push the bar back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '0758') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0759', 'بالا آوردن شانه روی نیمکت شیب‌دار اسمیت', 'Smith incline shoulder raises', 'chest', 'سینه', 'machine', 'دستگاه', 'دندانه‌ای قدامی', 'سرشانه، کول (ذوزنقه)', '۱. دستگاه اسمیت را برای حالت بالاسینه تنظیم کنید.
۲. رو به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۵. هالتر را با هدایت آرنج‌ها به سمت سقف بالا ببرید.
۶. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0759.gif', 'serratus', 'deltoids,trapezius', '1. Adjust the smith machine to an incline position.
2. Stand facing the machine with your feet shoulder-width apart.
3. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
4. Keep your back straight and core engaged.
5. Raise the barbell up towards the ceiling, leading with your elbows.
6. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
7. Repeat for the desired number of repetitions.', '0759') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0760', 'پرس پا اسمیت', 'Smith leg press', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. صندلی و سکوی پای دستگاه اسمیت را در وضعیت مناسب تنظیم کنید.
۲. روی دستگاه بنشینید، کمر به پشتی و پاها به اندازه عرض شانه روی سکو باشد.
۳. برای ثبات دستگیره‌ها یا کناره‌های دستگاه را بگیرید.
۴. با باز کردن پاها سکو را از خود دور کنید و کمر را به پشتی تکیه داده نگه دارید.
۵. لحظه‌ای در حالت کاملاً باز مکث کنید.
۶. زانوها را آرام خم کنید و سکو را به سمت خود برگردانید و به وضعیت شروع بازگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0760.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Adjust the seat and footplate of the smith machine to a comfortable position.
2. Sit on the machine with your back against the backrest and your feet shoulder-width apart on the footplate.
3. Grasp the handles or sides of the machine for stability.
4. Push the footplate away from you by extending your legs, keeping your back against the backrest.
5. Pause for a moment at the fully extended position.
6. Slowly bend your knees and lower the footplate back towards you, returning to the starting position.
7. Repeat for the desired number of repetitions.', '0760') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1434', 'اسکوات بار پایین اسمیت', 'Smith low bar squat', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. هالتر دستگاه اسمیت را در ارتفاعی تنظیم کنید که بتوانید آن را راحت روی بالای کمر قرار دهید.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۳. زیر میله بروید و آن را روی بالای کمر و روی عضلات کول قرار دهید.
۴. میله را با دست‌ها کمی بازتر از عرض شانه بگیرید.
۵. با صاف کردن پاها میله را از جایگاه بردارید و یک قدم عقب بروید.
۶. یک نفس عمیق بکشید و میان‌تنه را سفت کنید.
۷. اسکوات را با بردن لگن به عقب و خم کردن زانوها شروع کنید.
۸. بدن را تا جایی پایین ببرید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۹. در تمام حرکت سینه را بالا و کمر را صاف نگه دارید.
۱۰. با فشار پاشنه‌ها و باز کردن لگن و زانوها دوباره بایستید.
۱۱. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1434.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at a height that allows you to comfortably rest it on your upper back.
2. Stand with your feet shoulder-width apart, toes slightly turned outwards.
3. Step under the bar and position it across your upper back, resting it on your traps.
4. Grip the bar with your hands slightly wider than shoulder-width apart.
5. Unrack the bar by straightening your legs and stepping back from the rack.
6. Take a deep breath and brace your core.
7. Initiate the squat by pushing your hips back and bending your knees.
8. Lower your body until your thighs are parallel to the ground or slightly below.
9. Keep your chest up and your back straight throughout the movement.
10. Drive through your heels to stand back up, extending your hips and knees.
11. Repeat for the desired number of repetitions.', '1434') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1683', 'جلو بازو اسمیت', 'Smith machine bicep curl', 'arms', 'بازو', 'machine', 'دستگاه', 'جلو بازو', 'ساعد', '۱. ارتفاع میله اسمیت را در سطح کمر تنظیم کنید.
۲. رو به دستگاه اسمیت بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. میله را از زیر و کمی بازتر از عرض شانه بگیرید.
۴. آرنج‌ها را نزدیک پهلوها و بازوها را ثابت نگه دارید.
۵. با بازدم میله را با انقباض جلو بازو به سمت شانه‌ها بالا بیاورید.
۶. لحظه‌ای در اوج حرکت مکث کنید و جلو بازو را منقبض کنید.
۷. با دم، میله را آرام به وضعیت شروع پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1683.gif', 'biceps', 'forearm', '1. Adjust the height of the smith machine bar to be at waist level.
2. Stand facing the smith machine with your feet shoulder-width apart.
3. Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.
4. Keep your elbows close to your sides and your upper arms stationary.
5. Exhale and curl the bar up towards your shoulders, contracting your biceps.
6. Pause for a moment at the top of the movement, squeezing your biceps.
7. Inhale and slowly lower the bar back down to the starting position.
8. Repeat for the desired number of repetitions.', '1683') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1625', 'پرس زیرسینه دست جمع اسمیت', 'Smith machine decline close grip bench press', 'arms', 'بازو', 'machine', 'دستگاه', 'پشت بازو', 'سینه، شانه‌ها', '۱. نیمکت دستگاه اسمیت را برای حالت زیرسینه تنظیم کنید.
۲. روی نیمکت دراز بکشید و پاها را محکم روی زمین بگذارید.
۳. هالتر را با دست‌های جمع، کمی جمع‌تر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را نزدیک بدن نگه دارید.
۵. وقتی هالتر کمی بالاتر از سینه قرار گرفت لحظه‌ای مکث کنید.
۶. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1625.gif', 'triceps', 'chest,deltoids', '1. Adjust the bench on the smith machine to a decline position.
2. Lie down on the bench with your feet firmly planted on the ground.
3. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.
5. Pause for a moment when the barbell is just above your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1625') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1752', 'پشت بازو روی نیمکت شیب‌دار اسمیت', 'Smith machine incline tricep extension', 'arms', 'بازو', 'machine', 'دستگاه', 'پشت بازو', 'شانه‌ها', '۱. صندلی دستگاه اسمیت را طوری تنظیم کنید که میله در ارتفاع شانه باشد.
۲. روی نیمکت بنشینید، کمر به پد و کف پاها روی زمین باشد.
۳. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. دست‌ها را کاملاً صاف کنید، میله را از جایگاه بردارید و درست بالای سینه نگه دارید.
۵. میله را آرام به سمت پیشانی پایین بیاورید و آرنج‌ها را نزدیک سر نگه دارید.
۶. لحظه‌ای در پایین مکث کنید، سپس میله را به وضعیت شروع بالا ببرید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1752.gif', 'triceps', 'deltoids', '1. Adjust the seat of the smith machine so that the bar is at shoulder height.
2. Sit on the bench with your back against the pad and your feet flat on the ground.
3. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
4. Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.
5. Lower the bar slowly towards your forehead, keeping your elbows close to your head.
6. Pause for a moment at the bottom, then push the bar back up to the starting position.
7. Repeat for the desired number of repetitions.', '1752') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1626', 'پرس زیرسینه دست جمع دست‌برعکس اسمیت', 'Smith machine reverse decline close grip bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. دستگاه اسمیت را برای حالت زیرسینه تنظیم کنید.
۲. روی نیمکت دراز بکشید و پاها را زیر پدهای پا محکم کنید.
۳. هالتر را با دست‌های جمع، کمی جمع‌تر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۵. لحظه‌ای در پایین مکث کنید، سپس هالتر را به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1626.gif', 'chest', 'triceps,deltoids', '1. Adjust the smith machine to a decline position.
2. Lie down on the bench with your feet secured under the foot pads.
3. Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows tucked in.
5. Pause for a moment at the bottom, then push the barbell back up to the starting position.
6. Repeat for the desired number of repetitions.', '1626') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0761', 'زیربغل دست جمع اسمیت', 'Smith narrow row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، دلتوئید خلفی', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه با کف پاها روی زمین بنشینید.
۲. دستگیره‌ها را از رو و کمی جمع‌تر از عرض شانه بگیرید.
۳. کمر را صاف و سینه را بالا نگه دارید و دستگیره‌ها را به سمت بدن بکشید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در اوج حرکت مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0761.gif', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and position yourself on the machine with your feet flat on the floor.
2. Grasp the handles with an overhand grip, slightly narrower than shoulder-width apart.
3. Keep your back straight and your chest up as you pull the handles towards your body, squeezing your shoulder blades together.
4. Pause for a moment at the peak of the movement, then slowly release the handles back to the starting position.
5. Repeat for the desired number of repetitions.', '0761') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1360', 'زیربغل تک‌دست اسمیت', 'Smith one arm row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، ساعد', '۱. ارتفاع میله اسمیت را در سطح کمر تنظیم کنید.
۲. رو به دستگاه اسمیت بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۴. میله را با یک دست از رو با کف دست رو به پایین بگیرید.
۵. آرنج را نزدیک بدن نگه دارید و میله را به سمت کمر بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در اوج حرکت مکث کنید، سپس میله را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید، سپس دست را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1360.gif', 'upper-back', 'biceps,forearm', '1. Adjust the height of the smith machine bar to waist level.
2. Stand facing the smith machine with your feet shoulder-width apart.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Grasp the bar with one hand using an overhand grip, with your palm facing down.
5. Keep your elbow close to your body and pull the bar towards your waist, squeezing your shoulder blades together.
6. Pause for a moment at the top of the movement, then slowly lower the bar back to the starting position.
7. Repeat for the desired number of repetitions, then switch to the other arm.', '1360') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1393', 'ساق پا تک‌پا روی زمین اسمیت', 'Smith one leg floor calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. زیر میله دستگاه اسمیت، پشت به دستگاه روی زمین قرار بگیرید.
۲. پنجه پاها را روی یک سطح بلند مانند صفحه وزنه یا بلوک بگذارید.
۳. میله اسمیت را روی ساق پاها، کمی بالاتر از مچ قرار دهید.
۴. برای ثبات میله را با دست‌ها بگیرید.
۵. با باز کردن مچ پاها پاشنه‌ها را از زمین بلند کنید و بدن را بالا ببرید.
۶. در اوج حرکت مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1393.gif', 'calves', 'hamstring,gluteal', '1. Position yourself on the floor under the smith machine bar, facing away from the machine.
2. Place the balls of your feet on a raised surface, such as a weight plate or block.
3. Position the smith machine bar across your lower legs, just above your ankles.
4. Hold onto the bar with your hands for stability.
5. Raise your heels off the ground by extending your ankles, lifting your body up.
6. Pause at the top of the movement, then slowly lower your heels back down to the starting position.
7. Repeat for the desired number of repetitions.', '1393') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0762', 'زیربغل دلتوئید خلفی اسمیت', 'Smith rear delt row', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'کول (ذوزنقه)، متوازی‌الاضلاع، جلو بازو', '۱. ارتفاع صندلی را تنظیم کنید و طوری بنشینید که سینه روی پد و کف پاها روی زمین باشد.
۲. دستگیره‌ها را از رو و کمی بازتر از عرض شانه بگیرید.
۳. کمر را صاف و میان‌تنه را درگیر نگه دارید و دستگیره‌ها را به سمت سینه بکشید و کتف‌ها را به هم فشار دهید.
۴. لحظه‌ای در اوج حرکت مکث کنید، سپس دستگیره‌ها را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0762.gif', 'deltoids', 'trapezius,upper-back,biceps', '1. Adjust the seat height and position yourself on the machine with your chest against the pad and your feet flat on the ground.
2. Grasp the handles with an overhand grip, slightly wider than shoulder-width apart.
3. Keep your back straight and your core engaged as you pull the handles towards your chest, squeezing your shoulder blades together.
4. Pause for a moment at the top of the movement, then slowly release the handles back to the starting position.
5. Repeat for the desired number of repetitions.', '0762') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0763', 'ساق پا معکوس اسمیت', 'Smith reverse calf raises', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)', '۱. میله اسمیت را کمی پایین‌تر از شانه‌ها تنظیم کنید.
۲. رو به میله بایستید، پاها به اندازه عرض لگن باز و پنجه‌ها رو به جلو باشد.
۳. پنجه پاها را روی لبه پله یا سکو بگذارید و پاشنه‌ها آزاد باشند.
۴. برای حمایت میله را بگیرید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۵. پاشنه‌ها را تا جای ممکن بالا ببرید و وزن بدن را روی پنجه پاها منتقل کنید.
۶. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0763.gif', 'calves', 'hamstring', '1. Adjust the smith machine bar to a height just below your shoulders.
2. Stand facing the bar with your feet hip-width apart and toes pointing forward.
3. Place the balls of your feet on the edge of a step or platform, with your heels hanging off.
4. Hold onto the bar for support, keeping your back straight and core engaged.
5. Raise your heels as high as possible, lifting your body weight onto the balls of your feet.
6. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
7. Repeat for the desired number of repetitions.', '0763') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1394', 'ساق پا معکوس اسمیت (نسخه ۲)', 'Smith reverse calf raises', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)', '۱. میله اسمیت را کمی پایین‌تر از شانه‌ها تنظیم کنید.
۲. رو به میله بایستید، پاها به اندازه عرض لگن باز و پنجه‌ها رو به جلو باشد.
۳. پنجه پاها را روی لبه پله یا سکو بگذارید و پاشنه‌ها آزاد باشند.
۴. برای حمایت میله را بگیرید.
۵. پاشنه‌ها را تا جای ممکن بالا ببرید و بدن را روی پنجه‌ها بلند کنید.
۶. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1394.gif', 'calves', 'hamstring', '1. Adjust the smith machine bar to a height just below your shoulders.
2. Stand facing the bar with your feet hip-width apart and toes pointing forward.
3. Place the balls of your feet on the edge of a step or platform, with your heels hanging off.
4. Hold onto the bar for support.
5. Raise your heels as high as possible, lifting your body up onto your toes.
6. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
7. Repeat for the desired number of repetitions.', '1394') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1361', 'زیربغل خم دست‌برعکس اسمیت', 'Smith reverse grip bent over row', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'بالای پشت', 'جلو بازو، ساعد', '۱. دستگاه اسمیت را با میله در ارتفاع لگن تنظیم کنید.
۲. رو به میله بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۴. میله را از زیر و به اندازه عرض شانه بگیرید.
۵. میله را به سمت پایین سینه بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس میله را آرام به وضعیت شروع پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1361.gif', 'upper-back', 'biceps,forearm', '1. Set up the smith machine with the bar at hip height.
2. Stand facing the bar with your feet shoulder-width apart.
3. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
4. Grasp the bar with an underhand grip, hands shoulder-width apart.
5. Pull the bar towards your lower chest, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower the bar back down to the starting position.
7. Repeat for the desired number of repetitions.', '1361') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0764', 'پرس دست‌برعکس اسمیت', 'Smith reverse-grip press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. ارتفاع میله اسمیت را در سطح سینه تنظیم کنید.
۲. رو به میله بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. یک قدم عقب بروید و زانوها را کمی خم کنید.
۵. در طول تمرین سینه را بالا و میان‌تنه را درگیر نگه دارید.
۶. میله را به سمت سینه پایین بیاورید و آرنج‌ها را جمع نگه دارید.
۷. لحظه‌ای در پایین مکث کنید، سپس میله را به وضعیت شروع بالا ببرید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0764.gif', 'chest', 'triceps,deltoids', '1. Adjust the height of the smith machine bar to chest level.
2. Stand facing the bar with your feet shoulder-width apart.
3. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.
4. Step back and position yourself with a slight bend in your knees.
5. Keep your chest up and core engaged throughout the exercise.
6. Lower the bar towards your chest, keeping your elbows tucked in.
7. Pause for a moment at the bottom, then push the bar back up to the starting position.
8. Repeat for the desired number of repetitions.', '0764') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1395', 'ساق پا نشسته تک‌پا اسمیت', 'Smith seated one leg calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)', '۱. روی دستگاه بنشینید، کمر به پد و پاها روی جاپایی باشد.
۲. یک پا را روی جاپایی بگذارید و پای دیگر را از آن جدا نگه دارید.
۳. با کمک عضلات ساق، پاشنه را تا جای ممکن بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کرده و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1395.gif', 'calves', 'hamstring', '1. Sit on the machine with your back against the pad and your feet on the footrest.
2. Place one leg on the footrest and keep the other leg off the footrest.
3. Using your calf muscles, raise your heel as high as possible.
4. Pause for a moment at the top, then slowly lower your heel back down to the starting position.
5. Repeat for the desired number of repetitions, then switch legs and repeat.', '1395') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0765', 'پرس سرشانه نشسته اسمیت', 'Smith seated shoulder press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، بالای پشت', '۱. ارتفاع صندلی را طوری تنظیم کنید که دستگیره‌ها در سطح شانه باشند.
۲. روی دستگاه بنشینید، کمر به پد و کف پاها روی زمین باشد.
۳. دستگیره‌ها را از رو بگیرید و از تکیه‌گاه بلند کنید و دست‌ها را کاملاً صاف کنید.
۴. دستگیره‌ها را تا سطح شانه پایین بیاورید و آرنج‌ها را کمی خم نگه دارید.
۵. دستگیره‌ها را بالای سر پرس کنید تا دست‌ها کاملاً صاف شوند.
۶. لحظه‌ای در بالا مکث کنید، سپس دستگیره‌ها را آرام تا سطح شانه پایین بیاورید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0765.gif', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height so that the handles are at shoulder level.
2. Sit on the machine with your back against the pad and your feet flat on the floor.
3. Grasp the handles with an overhand grip and lift them off the supports, extending your arms fully.
4. Lower the handles down to shoulder level, keeping your elbows slightly bent.
5. Press the handles up overhead until your arms are fully extended.
6. Pause for a moment at the top, then slowly lower the handles back down to shoulder level.
7. Repeat for the desired number of repetitions.', '0765') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1426', 'مچ دست نشسته اسمیت', 'Smith seated wrist curl', 'arms', 'بازو', 'machine', 'دستگاه', 'ساعد', 'جلو بازو، بازویی', '۱. روی نیمکتی جلوی دستگاه اسمیت بنشینید و کف پاها را روی زمین بگذارید.
۲. هالتر را از زیر و به اندازه عرض شانه بگیرید.
۳. ساعدها را روی ران‌ها بگذارید و اجازه دهید مچ‌ها آویزان باشند.
۴. مچ‌ها را آرام به سمت بالا خم کنید و هالتر را به سمت ساعدها ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1426.gif', 'forearm', 'biceps', '1. Sit on a bench in front of a Smith machine with your feet flat on the ground.
2. Grasp the barbell with an underhand grip, hands shoulder-width apart.
3. Rest your forearms on your thighs, allowing your wrists to hang off.
4. Slowly curl your wrists upward, bringing the barbell towards your forearms.
5. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '1426') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0766', 'پرس سرشانه اسمیت', 'Smith shoulder press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، بالای پشت', '۱. ارتفاع صندلی را تنظیم کنید و روی دستگاه اسمیت با پاهای به اندازه عرض شانه قرار بگیرید.
۲. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۳. میله را از جایگاه بردارید و در سطح شانه با آرنج‌های خم و کف دست رو به جلو قرار دهید.
۴. میله را بالا پرس کنید تا دست‌ها کاملاً بالای سر صاف شوند.
۵. لحظه‌ای در بالا مکث کنید، سپس میله را آرام تا سطح شانه پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0766.gif', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height and position yourself on the smith machine with your feet shoulder-width apart.
2. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
3. Lift the bar off the rack and position it at shoulder level, with your elbows bent and palms facing forward.
4. Press the bar upward until your arms are fully extended overhead.
5. Pause for a moment at the top, then slowly lower the bar back down to shoulder level.
6. Repeat for the desired number of repetitions.', '0766') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0767', 'شراگ اسمیت', 'Smith shrug', 'back', 'پشت و زیربغل', 'machine', 'دستگاه', 'کول (ذوزنقه)', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. دست‌ها را صاف و شانه‌ها را رها نگه دارید.
۴. شانه‌ها را به سمت گوش‌ها بالا ببرید و در بالا عضلات کول را منقبض کنید.
۵. لحظه‌ای نگه دارید، سپس شانه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0767.gif', 'trapezius', 'deltoids', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Keep your arms straight and your shoulders relaxed.
4. Lift your shoulders up towards your ears, squeezing your traps at the top.
5. Hold for a moment, then slowly lower your shoulders back down to the starting position.
6. Repeat for the desired number of repetitions.', '0767') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0768', 'اسکوات اسپلیت تک‌پا اسمیت', 'Smith single leg split squat', 'legs', 'پا', 'machine', 'دستگاه', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. جلوی دستگاه اسمیت بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. یک پا را پشت سر روی نیمکت یا پله بگذارید و پنجه رو به جلو باشد.
۳. برای ثبات میله دستگاه اسمیت را بگیرید.
۴. زانوی جلو را خم کنید و به حالت لانج پایین بروید و کمر را صاف نگه دارید.
۵. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه پای جلو به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0768.gif', 'quadriceps', 'gluteal,hamstring', '1. Stand in front of the smith machine with your feet shoulder-width apart.
2. Place one foot behind you on a bench or step, with your toes pointing forward.
3. Hold onto the smith machine bar for stability.
4. Bend your front knee and lower your body down into a lunge position, keeping your back straight.
5. Pause for a moment at the bottom, then push through your front heel to return to the starting position.
6. Repeat for the desired number of repetitions, then switch legs.', '0768') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0769', 'لانج دوی سرعت اسمیت', 'Smith sprint lunge', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. دستگاه اسمیت را با هالتر در ارتفاع لگن تنظیم کنید.
۲. پشت به دستگاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. پای راست را عقب ببرید و روی پای خود را روی هالتر بگذارید.
۴. زانوی چپ را خم کنید و به حالت لانج پایین بروید و کمر را صاف نگه دارید.
۵. با فشار پاشنه چپ به وضعیت شروع برگردید.
۶. برای طرف دیگر با گام پای چپ به عقب تکرار کنید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0769.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at hip height.
2. Stand facing away from the machine with your feet shoulder-width apart.
3. Step back with your right foot and place it on the barbell, resting the top of your foot on the bar.
4. Bend your left knee and lower your body into a lunge position, keeping your back straight.
5. Push through your left heel to return to the starting position.
6. Repeat on the other side, stepping back with your left foot.
7. Continue alternating sides for the desired number of repetitions.', '0769') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0770', 'اسکوات اسمیت', 'Smith squat', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. هالتر دستگاه اسمیت را در ارتفاع مناسب برای اسکوات تنظیم کنید.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۳. زیر هالتر قرار بگیرید و آن را روی بالای کول و شانه‌ها قرار دهید.
۴. هالتر را باز و کمی بازتر از عرض شانه بگیرید.
۵. میان‌تنه را درگیر کنید و هالتر را از جایگاه بردارید و یک قدم عقب بروید.
۶. با سینه بالا و کمر صاف، اسکوات را با خم کردن لگن و زانوها شروع کنید.
۷. بدن را تا جایی پایین ببرید که ران‌ها موازی زمین یا کمی پایین‌تر باشند.
۸. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۹. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0770.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at an appropriate height for your squat.
2. Stand with your feet shoulder-width apart, toes slightly turned out.
3. Position yourself under the barbell, resting it on your upper traps and shoulders.
4. Grip the barbell with a wide grip, slightly wider than shoulder-width apart.
5. Engage your core and unrack the barbell, stepping back to clear the rack.
6. Keeping your chest up and back straight, initiate the squat by bending at the hips and knees.
7. Lower your body until your thighs are parallel to the ground or slightly below.
8. Pause for a moment at the bottom, then drive through your heels to return to the starting position.
9. Repeat for the desired number of repetitions.', '0770') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0771', 'مچ دست از پشت ایستاده اسمیت', 'Smith standing back wrist curl', 'arms', 'بازو', 'machine', 'دستگاه', 'ساعد', 'جلو بازو، پشت بازو', '۱. رو به دستگاه اسمیت بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. هالتر را از رو و به اندازه عرض شانه بگیرید.
۳. کمر را صاف و آرنج‌ها را نزدیک بدن نگه دارید.
۴. مچ‌ها را آرام به سمت بالا خم کنید و هالتر را به سمت بدن بیاورید.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0771.gif', 'forearm', 'biceps,triceps', '1. Stand facing the smith machine with your feet shoulder-width apart.
2. Grasp the barbell with an overhand grip, hands shoulder-width apart.
3. Keep your back straight and your elbows close to your body.
4. Slowly curl your wrists upwards, bringing the barbell towards your body.
5. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '0771') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0772', 'پرس نظامی پشت گردن ایستاده اسمیت', 'Smith standing behind head military press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، بالای پشت', '۱. ارتفاع دستگاه اسمیت را طوری تنظیم کنید که میله در سطح شانه باشد.
۲. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۳. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۴. میله را از جایگاه بردارید و یک قدم عقب بروید و وضعیت ثابتی بگیرید.
۵. میله را پشت سر و روی بالای کول قرار دهید.
۶. در طول تمرین میان‌تنه را درگیر و سینه را بالا نگه دارید.
۷. با صاف کردن کامل دست‌ها میله را بالای سر پرس کنید.
۸. لحظه‌ای کوتاه در اوج حرکت مکث کنید، سپس میله را آرام به وضعیت شروع پایین بیاورید.
۹. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0772.gif', 'deltoids', 'triceps,upper-back', '1. Adjust the seat height of the smith machine so that the bar is at shoulder level.
2. Stand with your feet shoulder-width apart and your knees slightly bent.
3. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
4. Lift the bar off the rack and step back, maintaining a stable stance.
5. Position the bar behind your head, resting on your upper traps.
6. Keep your core engaged and your chest lifted throughout the exercise.
7. Press the bar overhead by extending your arms, fully straightening them.
8. Pause briefly at the top of the movement, then slowly lower the bar back down to the starting position.
9. Repeat for the desired number of repetitions.', '0772') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0773', 'ساق پا ایستاده اسمیت', 'Smith standing leg calf raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. میله اسمیت را در ارتفاعی تنظیم کنید که با کف پاها روی زمین بایستید و شانه‌ها زیر میله باشند.
۲. زیر میله با پاهای به اندازه عرض شانه و پنجه‌های رو به جلو قرار بگیرید.
۳. برای ثبات دست‌ها را روی میله بگذارید.
۴. ساق‌ها را درگیر کنید و پاشنه‌ها را آرام از زمین بلند کنید و بدن را روی پنجه‌ها ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0773.gif', 'calves', 'hamstring,gluteal', '1. Adjust the smith machine bar to a height that allows you to stand with your feet flat on the ground and your shoulders under the bar.
2. Position yourself under the bar with your feet shoulder-width apart and your toes pointing forward.
3. Place your hands on the bar for stability.
4. Engage your calves and slowly raise your heels off the ground, lifting your body up onto your toes.
5. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
6. Repeat for the desired number of repetitions.', '0773') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0774', 'پرس نظامی ایستاده اسمیت', 'Smith standing military press', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. هالتر را از جایگاه بردارید و تا سطح شانه با کف دست رو به جلو پایین بیاورید.
۴. هالتر را بالا پرس کنید تا دست‌ها کاملاً بالای سر صاف شوند.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام تا سطح شانه پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0774.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.
3. Lift the barbell off the rack and bring it down to shoulder level, with your palms facing forward.
4. Press the barbell upward until your arms are fully extended overhead.
5. Pause for a moment at the top, then slowly lower the barbell back down to shoulder level.
6. Repeat for the desired number of repetitions.', '0774') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3142', 'اسکوات سومو اسمیت', 'Smith sumo squat', 'legs', 'پا', 'machine', 'دستگاه', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. دستگاه اسمیت را با هالتر در ارتفاع لگن تنظیم کنید.
۲. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را به بیرون بچرخانید.
۳. زیر هالتر قرار بگیرید و آن را روی بالای کمر و شانه‌ها قرار دهید.
۴. میان‌تنه را درگیر و سینه را بالا نگه دارید و با بردن لگن به عقب و خم کردن زانوها به حالت اسکوات پایین بروید.
۵. تا جایی پایین بروید که ران‌ها موازی زمین شوند یا تا جایی که راحت هستید.
۶. لحظه‌ای در پایین مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3142.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Set up the smith machine with the barbell at hip height.
2. Stand with your feet wider than shoulder-width apart, toes pointing outwards.
3. Position yourself under the barbell, resting it on your upper back and shoulders.
4. Engage your core and keep your chest up as you lower your body down into a squat position, pushing your hips back and bending your knees.
5. Lower yourself until your thighs are parallel to the ground, or as low as you can comfortably go.
6. Pause for a moment at the bottom, then push through your heels to return to the starting position.
7. Repeat for the desired number of repetitions.', '3142') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1396', 'بالا آوردن پنجه پا اسمیت', 'Smith toe raise', 'legs', 'پا', 'machine', 'دستگاه', 'ساق پا', 'مچ پا، ساق جلویی', '۱. میله اسمیت را در ارتفاعی تنظیم کنید که بتوانید با کف پاها روی زمین راحت بایستید.
۲. زیر میله قرار بگیرید، شانه‌ها درست زیر آن و پاها به اندازه عرض شانه باز باشد.
۳. پنجه پاها را روی یک سکوی بلند یا صفحه وزنه بگذارید و پاشنه‌ها آزاد باشند.
۴. میله را از رو و کمی بازتر از عرض شانه بگیرید.
۵. در طول تمرین میان‌تنه را درگیر و کمر را صاف نگه دارید.
۶. پاشنه‌ها را آرام تا جای ممکن بالا ببرید و وزن بدن را روی پنجه پاها ببرید.
۷. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1396.gif', 'calves', 'tibialis', '1. Adjust the smith machine bar to a height that allows you to comfortably stand with your feet flat on the ground.
2. Position yourself under the bar with your shoulders directly below it and your feet shoulder-width apart.
3. Place the balls of your feet on a raised platform or weight plates, with your heels hanging off the edge.
4. Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.
5. Engage your core and keep your back straight throughout the exercise.
6. Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.
7. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
8. Repeat for the desired number of repetitions.', '1396') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0775', 'کول ایستاده اسمیت', 'Smith upright row', 'shoulders', 'سرشانه', 'machine', 'دستگاه', 'سرشانه', 'کول (ذوزنقه)، جلو بازو', '۱. رو به دستگاه اسمیت بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. هالتر را از رو و کمی بازتر از عرض شانه بگیرید.
۳. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۴. هالتر را با هدایت آرنج‌ها به سمت چانه بالا بکشید.
۵. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0775.gif', 'deltoids', 'trapezius,biceps', '1. Stand with your feet shoulder-width apart, facing the smith machine.
2. Grasp the barbell with an overhand grip, hands slightly wider than shoulder-width apart.
3. Keep your back straight and your core engaged.
4. Pull the barbell up towards your chin, leading with your elbows.
5. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
6. Repeat for the desired number of repetitions.', '0775') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1308', 'پرس سینه دست باز اسمیت', 'Smith wide grip bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. نیمکت را در وضعیت مناسب زیر دستگاه اسمیت قرار دهید.
۲. روی نیمکت دراز بکشید و کف پاها را روی زمین بگذارید.
۳. هالتر را باز و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را به طرفین باز نگه دارید.
۵. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید.
۶. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1308.gif', 'chest', 'triceps,deltoids', '1. Adjust the bench to a comfortable position on the smith machine.
2. Lie down on the bench with your feet flat on the ground.
3. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows out to the sides.
5. Pause for a moment when the barbell touches your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1308') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1309', 'پرس زیرسینه دست باز اسمیت', 'Smith wide grip decline bench press', 'chest', 'سینه', 'machine', 'دستگاه', 'سینه', 'پشت بازو، شانه‌ها', '۱. نیمکت زیرسینه را روی زاویه دلخواه تنظیم کنید.
۲. روی نیمکت دراز بکشید و پاها را زیر پدهای پا محکم کنید.
۳. هالتر را باز و کمی بازتر از عرض شانه بگیرید.
۴. هالتر را از جایگاه بردارید و آرام به سمت سینه پایین بیاورید و آرنج‌ها را رو به بیرون نگه دارید.
۵. وقتی هالتر به سینه رسید لحظه‌ای مکث کنید.
۶. هالتر را به وضعیت شروع بالا ببرید و دست‌ها را کاملاً صاف کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1309.gif', 'chest', 'triceps,deltoids', '1. Adjust the decline bench to the desired angle.
2. Lie down on the bench with your feet secured under the foot pads.
3. Grasp the barbell with a wide grip, slightly wider than shoulder-width apart.
4. Unrack the barbell and lower it slowly towards your chest, keeping your elbows pointed outwards.
5. Pause for a moment when the barbell touches your chest.
6. Push the barbell back up to the starting position, fully extending your arms.
7. Repeat for the desired number of repetitions.', '1309') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0776', 'اسنچ پول', 'Snatch pull', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'همسترینگ (پشت ران)، سرینی (باسن)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر روی زمین جلوی شما باشد.
۲. زانوها را خم کنید و از لگن خم شوید و به حالت اسکوات پایین بروید و هالتر را از رو بگیرید.
۳. کمر را صاف و سینه را بالا نگه دارید و با فشار پاشنه‌ها و باز کردن لگن و زانوها هالتر را از زمین بلند کنید.
۴. وقتی هالتر به سطح لگن رسید، آن را انفجاری بالا بکشید، شانه‌ها را بالا بیندازید و آرنج‌ها را بالا و به طرفین ببرید.
۵. وقتی هالتر به بالاترین نقطه رسید، سریع زیر آن بروید و به حالت اسکوات عمیق بروید.
۶. هالتر را بالای سر با دست‌های کاملاً صاف و زانوهای خم بگیرید.
۷. با باز کردن لگن و زانوها بایستید و هالتر را بالای سر نگه دارید.
۸. با معکوس کردن حرکت هالتر را به وضعیت شروع پایین بیاورید.
۹. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0776.gif', 'quadriceps', 'hamstring,gluteal,calves', '1. Stand with your feet shoulder-width apart and the barbell on the ground in front of you.
2. Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with an overhand grip.
3. Keep your back straight and chest up as you drive through your heels to lift the barbell off the ground, extending your hips and knees.
4. As the barbell reaches hip level, explosively pull it upwards, shrugging your shoulders and pulling your elbows high and to the sides.
5. As the barbell reaches its highest point, quickly drop underneath it, pulling yourself into a deep squat position.
6. Catch the barbell overhead with your arms fully extended and your knees bent.
7. Stand up by extending your hips and knees, keeping the barbell overhead.
8. Lower the barbell back down to the starting position by reversing the movement.
9. Repeat for the desired number of repetitions.', '0776') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0777', 'جادوگر (اسپل‌کستر)', 'Spell caster', 'core', 'شکم و میان‌تنه', 'dumbbell', 'دمبل', 'شکم', 'پهلوها، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و یک دمبل در یک دست بگیرید.
۲. زانوها را کمی خم کنید و از کمر به جلو خم شوید و کمر را صاف نگه دارید.
۳. دست دارای دمبل را به سمت پای مخالف دراز کنید و همزمان تنه را بچرخانید.
۴. به وضعیت شروع برگردید و برای طرف دیگر تکرار کنید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0777.gif', 'abs', 'obliques,lower-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in one hand.
2. Bend your knees slightly and hinge forward at the waist, keeping your back straight.
3. Extend your arm with the dumbbell towards the opposite foot, rotating your torso as you do so.
4. Return to the starting position and repeat on the other side.
5. Continue alternating sides for the desired number of repetitions.', '0777') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1362', 'حالت ابوالهول', 'Sphinx', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. روی زمین دمر دراز بکشید، ساعدها صاف روی زمین و آرنج‌ها درست زیر شانه‌ها باشد.
۲. میان‌تنه را درگیر کنید و سینه را از زمین بلند کنید و ساعدها و پنجه‌ها روی زمین بمانند.
۳. این وضعیت را چند ثانیه نگه دارید و گردن را در حالت طبیعی نگه دارید.
۴. سینه را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1362.gif', 'lower-back', 'gluteal,hamstring', '1. Lie face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.
2. Engage your core and lift your chest off the ground, keeping your forearms and toes on the floor.
3. Hold this position for a few seconds, making sure to keep your neck in a neutral position.
4. Slowly lower your chest back down to the starting position.
5. Repeat for the desired number of repetitions.', '1362') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0778', 'شنا سوئدی خزیدن عنکبوتی', 'Spider crawl push up', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'میان‌تنه، سینه، شانه‌ها', '۱. در وضعیت شنا قرار بگیرید، دست‌ها کمی بازتر از عرض شانه و پاها جفت باشد.
۲. زانوی راست را به سمت آرنج راست بیاورید و از زمین جدا نگه دارید.
۳. هنگام برگرداندن زانوی راست، همزمان با خم کردن آرنج‌ها بدن را به سمت زمین پایین ببرید.
۴. به وضعیت شروع بالا بروید و با زانوی چپ به سمت آرنج چپ تکرار کنید.
۵. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0778.gif', 'gluteal', 'abs,chest,deltoids', '1. Start in a push-up position with your hands slightly wider than shoulder-width apart and your feet together.
2. Bring your right knee towards your right elbow, keeping it off the ground.
3. As you bring your right knee back, simultaneously lower your body towards the ground by bending your elbows.
4. Push back up to the starting position and repeat with your left knee towards your left elbow.
5. Continue alternating sides for the desired number of repetitions.', '0778') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1363', 'کشش ستون فقرات', 'Spine stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'فیله کمر', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. روی زمین بنشینید و پاها را جلوی خود صاف دراز کنید.
۲. دست‌ها را پشت سر با انگشتان رو به بدن روی زمین بگذارید.
۳. میان‌تنه را درگیر کنید و آرام به عقب متمایل شوید و کمر را صاف نگه دارید.
۴. تا جایی به عقب بروید که کشش را در ستون فقرات حس کنید.
۵. کشش را چند ثانیه نگه دارید، سپس آرام به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1363.gif', 'lower-back', 'hamstring,gluteal', '1. Sit on the ground with your legs extended in front of you.
2. Place your hands on the ground behind you, fingers pointing towards your body.
3. Engage your core and slowly lean back, keeping your back straight.
4. Continue leaning back until you feel a stretch in your spine.
5. Hold the stretch for a few seconds, then slowly return to the starting position.
6. Repeat for the desired number of repetitions.', '1363') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2329', 'چرخش ستون فقرات', 'Spine twist', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، پایین کمر', '۱. روی زمین بنشینید و پاها را جلوی خود صاف دراز کنید.
۲. زانوها را خم کنید و کف پاها را به اندازه عرض لگن روی زمین بگذارید.
۳. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۴. شکم را درگیر کنید و تنه را آرام به راست بچرخانید و آرنج راست را به سمت زانوی چپ ببرید.
۵. لحظه‌ای در انتهای چرخش مکث کنید، سپس آرام به وضعیت شروع برگردید.
۶. چرخش را به سمت چپ تکرار کنید و آرنج چپ را به سمت زانوی راست ببرید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2329.gif', 'abs', 'obliques,lower-back', '1. Sit on the ground with your legs extended in front of you.
2. Bend your knees and place your feet flat on the ground, hip-width apart.
3. Place your hands behind your head with your elbows pointing outwards.
4. Engage your abs and slowly twist your torso to the right, bringing your right elbow towards your left knee.
5. Pause for a moment at the end of the twist, then slowly return to the starting position.
6. Repeat the twist to the left side, bringing your left elbow towards your right knee.
7. Continue alternating sides for the desired number of repetitions.', '2329') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2368', 'اسکوات اسپلیت', 'Split squats', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. با یک پا یک گام به جلو بردارید و آن را حدود ۶۰ سانتی‌متر جلوتر از پای دیگر بگذارید.
۳. با خم کردن زانوها و لگن بدن را پایین ببرید و کمر را صاف نگه دارید.
۴. تا جایی پایین بروید که ران جلو موازی زمین شود و زانوی عقب کمی بالاتر از زمین باشد.
۵. لحظه‌ای مکث کنید، سپس با فشار پاشنه پای جلو به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کرده و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2368.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Take a step forward with one foot and place it about two feet in front of the other foot.
3. Lower your body by bending your knees and hips, keeping your back straight.
4. Continue lowering until your front thigh is parallel to the ground, and your back knee is hovering just above the ground.
5. Pause for a moment, then push through your front heel to return to the starting position.
6. Repeat for the desired number of repetitions, then switch legs and repeat.', '2368') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0786', 'اسکوات جرک', 'Squat jerk', 'legs', 'پا', 'barbell', 'هالتر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا، میان‌تنه', '۱. با هالتر روی شانه‌ها و پاهای به اندازه عرض شانه شروع کنید.
۲. به حالت اسکوات پایین بروید، سینه را بالا و زانوها را در راستای پنجه پا نگه دارید.
۳. در پایین اسکوات، با قدرت انفجاری پاها هالتر را بالای سر برانید.
۴. وقتی هالتر به اوج رسید، سریع به حالت اسپلیت بروید؛ یک پا جلو و یک پا عقب.
۵. هالتر را بالای سر با دست‌های کاملاً صاف و زانوی عقب نزدیک به زمین بگیرید.
۶. از حالت اسپلیت بایستید و پاها را کنار هم بیاورید.
۷. هالتر را به شانه‌ها برگردانید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0786.gif', 'quadriceps', 'gluteal,hamstring,calves,abs', '1. Start with the barbell resting on your shoulders, with your feet shoulder-width apart.
2. Lower your body into a squat position, keeping your chest up and your knees tracking over your toes.
3. As you reach the bottom of the squat, explosively drive through your legs and push the barbell overhead.
4. As the barbell reaches its peak, quickly drop into a split position, with one foot forward and one foot back.
5. Catch the barbell overhead with your arms fully extended and your back knee slightly touching the ground.
6. Stand up from the split position, bringing your feet back together.
7. Lower the barbell back to your shoulders and repeat for the desired number of repetitions.', '0786') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1705', 'اسکوات روی بوسو', 'Squat on bosu ball', 'legs', 'پا', 'other', 'سایر', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. بوسو را با سمت صاف رو به بالا روی زمین بگذارید.
۲. با پاهای به اندازه عرض شانه روی بوسو بایستید.
۳. با خم کردن زانوها و لگن، مانند نشستن روی صندلی، بدن را پایین ببرید.
۴. سینه را بالا و وزن را روی پاشنه‌ها نگه دارید.
۵. تا جایی پایین بروید که ران‌ها موازی زمین شوند.
۶. لحظه‌ای مکث کنید، سپس با فشار پاشنه‌ها به وضعیت شروع برگردید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1705.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Place the bosu ball on the ground with the flat side up.
2. Stand with your feet shoulder-width apart and position yourself on top of the bosu ball.
3. Lower your body down by bending your knees and hips, as if sitting back into a chair.
4. Keep your chest up and your weight on your heels.
5. Lower yourself until your thighs are parallel to the ground.
6. Pause for a moment, then push through your heels to return to the starting position.
7. Repeat for the desired number of repetitions.', '1705') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1685', 'اسکوات و کشش بالای سر', 'Squat to overhead reach', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید.
۳. هنگام بالا آمدن از اسکوات، دست‌ها را بالای سر به سمت سقف دراز کنید.
۴. با پایین آوردن دست‌ها و خم کردن زانوها دوباره به اسکوات بروید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1685.gif', 'quadriceps', 'gluteal,hamstring,abs', '1. Stand with your feet shoulder-width apart and toes slightly turned out.
2. Lower your body down into a squat position by bending your knees and pushing your hips back.
3. As you come up from the squat, extend your arms overhead, reaching towards the ceiling.
4. Return to the starting position by lowering your arms and bending your knees to squat down again.
5. Repeat for the desired number of repetitions.', '1685') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1686', 'اسکوات و کشش بالای سر با چرخش', 'Squat to overhead reach with twist', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. با خم کردن زانوها و بردن لگن به عقب به حالت اسکوات پایین بروید.
۳. هنگام بالا آمدن از اسکوات، دست‌ها را بالای سر ببرید و تنه را به یک طرف بچرخانید.
۴. به وضعیت شروع برگردید و اسکوات را تکرار کنید، این بار تنه را به طرف مقابل بچرخانید.
۵. در هر تکرار اسکوات طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1686.gif', 'quadriceps', 'gluteal,hamstring,abs', '1. Stand with your feet shoulder-width apart and toes slightly turned out.
2. Lower your body into a squat position by bending your knees and pushing your hips back.
3. As you come up from the squat, raise your arms overhead and twist your torso to one side.
4. Return to the starting position and repeat the squat, this time twisting your torso to the opposite side.
5. Continue alternating sides with each squat repetition.', '1686') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2297', 'کرانچ روی توپ تعادلی (دامنه کامل، دست پشت سر)', 'Stability ball crunch (full range hands behind head)', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'خم‌کننده ران', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن شکم، بالاتنه را آرام به جلو خم کنید و سینه را به سمت زانوها ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2297.gif', 'abs', 'hip-flexors', '1. Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, slowly curl your upper body forward, bringing your chest towards your knees.
4. Pause for a moment at the top, then slowly lower your upper body back to the starting position.
5. Repeat for the desired number of repetitions.', '2297') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3291', 'پرس استالدر', 'Stalder press', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'شانه‌ها، میان‌تنه', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را بالای سر دراز کنید.
۲. زانوها را کمی خم کنید و میان‌تنه را درگیر کنید.
۳. با دست‌های کشیده بالای سر، به حالت اسکوات پایین بروید.
۴. هنگام پایین رفتن دست‌ها را به سمت زمین فشار دهید و پشت بازو را درگیر کنید.
۵. لحظه‌ای در پایین اسکوات مکث کنید، سپس با فشار پاشنه‌ها بایستید و همزمان دست‌ها را دوباره بالای سر ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3291.gif', 'triceps', 'deltoids,abs', '1. Start by standing with your feet shoulder-width apart and your arms extended overhead.
2. Bend your knees slightly and engage your core.
3. Lower your body down into a squat position while keeping your arms extended overhead.
4. As you squat down, press your arms down towards the ground, engaging your triceps.
5. Pause for a moment at the bottom of the squat, then push through your heels to stand back up while simultaneously raising your arms back overhead.
6. Repeat for the desired number of repetitions.', '3291') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3669', 'آرچر ایستاده', 'Standing archer', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'شانه‌ها، جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. دست‌ها را صاف جلوی بدن در ارتفاع شانه و موازی زمین دراز کنید.
۳. تنه را به راست بچرخانید و دست‌ها را کشیده و کمر را صاف نگه دارید.
۴. هنگام چرخش، دست راست را جلو و دست چپ را عقب ببرید، مانند کشیدن زه کمان.
۵. وضعیت را لحظه‌ای نگه دارید، سپس به وضعیت شروع برگردید.
۶. حرکت را تکرار کنید، این بار تنه را به چپ بچرخانید و دست چپ را جلو و دست راست را عقب ببرید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3669.gif', 'upper-back', 'deltoids,biceps,forearm', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Extend your arms straight out in front of you at shoulder height, parallel to the ground.
3. Rotate your torso to the right, keeping your arms extended and your back straight.
4. As you rotate, extend your right arm forward and your left arm back, mimicking the motion of drawing a bowstring.
5. Hold the position for a moment, then return to the starting position.
6. Repeat the motion, this time rotating your torso to the left and extending your left arm forward and your right arm back.
7. Continue alternating sides for the desired number of repetitions.', '3669') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0788', 'پرس پشت گردن ایستاده', 'Standing behind neck press', 'shoulders', 'سرشانه', 'barbell', 'هالتر', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و هالتر را از رو پشت گردن نگه دارید.
۲. کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. با صاف کردن دست‌ها و باز کردن کامل آرنج‌ها هالتر را بالای سر پرس کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس هالتر را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0788.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and hold the barbell behind your neck with an overhand grip.
2. Keep your back straight and core engaged.
3. Press the barbell overhead by extending your arms, fully extending your elbows.
4. Pause for a moment at the top, then slowly lower the barbell back down to the starting position.
5. Repeat for the desired number of repetitions.', '0788') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1490', 'ساق پا ایستاده (روی پله)', 'Standing calf raise (on a staircase)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'مچ پا، پاها', '۱. روی لبه پله یا سکوی محکم بایستید، پنجه‌ها روی پله و پاشنه‌ها آزاد باشند.
۲. در صورت نیاز برای تعادل نرده یا دیوار را بگیرید.
۳. پاشنه‌ها را آرام تا جای ممکن بالا ببرید و وزن بدن را روی پنجه پاها ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1490.gif', 'calves', '', '1. Stand on the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.
2. Hold onto a railing or wall for balance if needed.
3. Slowly raise your heels as high as possible, lifting your body weight onto the balls of your feet.
4. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '1490') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1397', 'ساق پا ایستاده', 'Standing calves', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و پنجه‌ها رو به جلو باشد.
۲. پاشنه‌ها را تا جای ممکن بالا ببرید و روی پنجه‌ها بایستید.
۳. وضعیت را لحظه‌ای نگه دارید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1397.gif', 'calves', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart, toes pointing forward.
2. Raise your heels off the ground as high as possible, standing on your toes.
3. Hold the position for a moment, then slowly lower your heels back down to the starting position.
4. Repeat for the desired number of repetitions.', '1397') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1398', 'کشش ساق پا ایستاده', 'Standing calves calf stretch', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. رو به دیوار یا جسمی محکم به اندازه طول دست از آن بایستید.
۲. دست‌ها را در ارتفاع شانه روی دیوار یا جسم بگذارید.
۳. یک پا را به عقب ببرید و پاشنه را صاف روی زمین نگه دارید.
۴. زانوی جلو را کمی خم کنید و به جلو متمایل شوید و پای عقب را صاف نگه دارید.
۵. باید کشش را در عضله ساق پا حس کنید.
۶. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۷. با پای دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1398.gif', 'calves', 'hamstring,gluteal', '1. Stand facing a wall or sturdy object, about an arm''s length away.
2. Place your hands on the wall or object at shoulder height.
3. Step back with one foot, keeping your heel flat on the ground.
4. Bend your front knee slightly and lean forward, keeping your back leg straight.
5. You should feel a stretch in your calf muscle.
6. Hold the stretch for 20-30 seconds.
7. Repeat on the other leg.', '1398') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1599', 'کشش همسترینگ و ساق پا ایستاده با تسمه', 'Standing hamstring and calf stretch with strap', 'legs', 'پا', 'other', 'سایر', 'همسترینگ (پشت ران)', 'ساق پا', '۱. صاف بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. تسمه را با دو دست بگیرید و دور پنجه پا بیندازید.
۳. پا را صاف نگه دارید و آرام از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۴. کشش را در همسترینگ و ساق پا حس کنید.
۵. کشش را ۲۰ تا ۳۰ ثانیه نگه دارید.
۶. کشش را رها کنید و با پای دیگر تکرار کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1599.gif', 'hamstring', 'calves', '1. Stand upright with your feet shoulder-width apart.
2. Hold the strap with both hands and place it around the ball of your foot.
3. Keep your leg straight and slowly lean forward from your hips, keeping your back straight.
4. Feel the stretch in your hamstring and calf muscles.
5. Hold the stretch for 20-30 seconds.
6. Release the stretch and repeat with the other leg.
7. Repeat for the desired number of repetitions.', '1599') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0794', 'کشش جانبی ایستاده', 'Standing lateral stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'شانه‌ها، پهلوها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. دست‌ها را صاف به طرفین و موازی زمین باز کنید.
۳. بالاتنه را آرام به یک طرف خم کنید تا کشش را در پهلو و زیربغل حس کنید.
۴. کشش را ۱۵ تا ۳۰ ثانیه نگه دارید.
۵. به وضعیت شروع برگردید و برای طرف دیگر تکرار کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0794.gif', 'upper-back', 'deltoids,obliques', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Extend your arms straight out to the sides, parallel to the ground.
3. Slowly lean your upper body to one side, feeling a stretch in your side and lats.
4. Hold the stretch for 15-30 seconds.
5. Return to the starting position and repeat on the other side.
6. Repeat for the desired number of repetitions.', '0794') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1364', 'تیلت لگن ایستاده', 'Standing pelvic tilt', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'فیله کمر', 'شکم', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. دست‌ها را روی لگن بگذارید یا کنار بدن آویزان کنید.
۳. عضلات میان‌تنه را درگیر کنید و لگن را به جلو متمایل کنید و پایین کمر را به سمت دیوار پشت سر فشار دهید.
۴. وضعیت را چند ثانیه نگه دارید، سپس رها کنید و به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1364.gif', 'lower-back', 'abs', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Place your hands on your hips or let them hang by your sides.
3. Engage your core muscles and tilt your pelvis forward, pushing your lower back towards the wall behind you.
4. Hold the position for a few seconds, then release and return to the starting position.
5. Repeat for the desired number of repetitions.', '1364') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0795', 'پشت پا تک‌پا ایستاده', 'Standing single leg curl', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'همسترینگ (پشت ران)', 'سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض لگن باز کنید و دست‌ها را روی لگن بگذارید.
۲. وزن را روی پای چپ منتقل کنید و پای راست را با زانوی خم از زمین بلند کنید.
۳. پاشنه راست را آرام به سمت باسن بیاورید و همسترینگ را منقبض کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس پای راست را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0795.gif', 'hamstring', 'gluteal', '1. Stand with your feet hip-width apart and your hands on your hips.
2. Shift your weight onto your left leg and lift your right foot off the ground, bending your knee.
3. Slowly curl your right heel towards your glutes, squeezing your hamstring.
4. Pause for a moment at the top, then slowly lower your right foot back down to the starting position.
5. Repeat for the desired number of repetitions, then switch legs.', '0795') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0796', 'چرخ شکم ایستاده', 'Standing wheel rollerout', 'core', 'شکم و میان‌تنه', 'other', 'سایر', 'شکم', 'پایین کمر، شانه‌ها', '۱. صاف بایستید، پاها را به اندازه عرض شانه باز کنید و چرخ شکم جلوی شما باشد.
۲. از کمر خم شوید و چرخ را آرام به جلو بغلتانید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۳. تا جایی به جلو بغلتانید که کشش را در شکم حس کنید و بدن تا حد ممکن کشیده شود.
۴. لحظه‌ای مکث کنید، سپس چرخ را آرام به سمت بدن برگردانید و به وضعیت شروع بازگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0796.gif', 'abs', 'lower-back,deltoids', '1. Start by standing tall with your feet shoulder-width apart and the wheel roller in front of you.
2. Bend at your waist and slowly roll the wheel forward, keeping your back straight and your core engaged.
3. Continue rolling forward until you feel a stretch in your abs and your body is extended as far as possible.
4. Pause for a moment, then slowly roll the wheel back towards your body, returning to the starting position.
5. Repeat for the desired number of repetitions.', '0796') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3314', 'مالتیز پا باز', 'Straddle maltese', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، سینه', '۱. از یک جفت حلقه با دست‌های کاملاً صاف و بدن در یک خط صاف آویزان شوید.
۲. پاها را کاملاً باز کنید تا حالت پا باز ایجاد شود.
۳. میان‌تنه را درگیر کنید و بدن را آرام پایین ببرید تا دست‌ها موازی زمین شوند.
۴. این وضعیت را چند ثانیه نگه دارید، سپس خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3314.gif', 'abs', 'deltoids,chest', '1. Start by hanging from a pair of rings with your arms fully extended and your body in a straight line.
2. Spread your legs wide apart, forming a straddle position.
3. Engage your core and slowly lower your body until your arms are parallel to the ground.
4. Hold this position for a few seconds, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '3314') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3298', 'پلانچ پا باز', 'Straddle planche', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'شانه‌ها، پشت بازو، سینه', '۱. در وضعیت شنا قرار بگیرید، دست‌ها به اندازه عرض شانه و پاها کاملاً باز باشد.
۲. میان‌تنه را درگیر کنید و وزن را آرام به جلو منتقل کنید تا شانه‌ها بالای دست‌ها قرار گیرند.
۳. آرنج‌ها را خم کنید و بدن را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس با فشار دست‌ها، دست‌ها را صاف کنید و بدن را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3298.gif', 'abs', 'deltoids,triceps,chest', '1. Start in a push-up position with your hands shoulder-width apart and your feet spread wide apart.
2. Engage your core and slowly shift your weight forward, bringing your shoulders over your hands.
3. Bend your elbows and lower your body towards the ground, keeping your elbows close to your sides.
4. Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.
5. Repeat for the desired number of repetitions.', '3298') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1427', 'دور کردن ران با پای صاف', 'Straight leg outer hip abductor', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'دورکننده ران', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. به پهلو دراز بکشید و پاها را صاف و روی هم قرار دهید.
۲. برای حمایت دست زیرین را زیر سر بگذارید.
۳. میان‌تنه را درگیر کنید و پای بالایی را بدون چرخاندن لگن یا خم شدن به عقب تا جای ممکن بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پا را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس طرف را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1427.gif', 'gluteal', 'hamstring', '1. Lie on your side with your legs straight and stacked on top of each other.
2. Place your bottom arm under your head for support.
3. Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.
4. Pause for a moment at the top, then slowly lower your leg back down to the starting position.
5. Repeat for the desired number of repetitions, then switch sides.', '1427') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0803', 'شنا سوئدی سوپرمن', 'Superman push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'میان‌تنه، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها کمی بازتر از عرض شانه و پاها جفت باشد.
۲. میان‌تنه را درگیر کنید و بدن را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۳. هنگام پایین رفتن، همزمان دست راست و پای چپ را از زمین بلند کنید و صاف دراز کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس دست و پا را پایین بیاورید و خود را به وضعیت شروع بالا ببرید.
۵. حرکت را تکرار کنید و این بار دست چپ و پای راست را بلند کنید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0803.gif', 'chest', 'abs,deltoids', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.
2. Engage your core and lower your body towards the ground, keeping your elbows close to your sides.
3. As you lower your body, simultaneously lift your right arm and left leg off the ground, extending them straight out.
4. Pause for a moment at the top, then lower your arm and leg back down while pushing yourself back up to the starting position.
5. Repeat the movement, this time lifting your left arm and right leg.
6. Continue alternating sides for the desired number of repetitions.', '0803') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0805', 'فال‌اوت شکم معلق', 'Suspended abdominal fallout', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، خم‌کننده ران', '۱. تی‌آر‌ایکس را به یک نقطه اتصال بلند وصل کنید و تسمه‌ها را در ارتفاع کمر تنظیم کنید.
۲. پشت به نقطه اتصال بایستید و دستگیره‌ها را با دست‌های کشیده جلوی بدن بگیرید.
۳. از کمر به جلو متمایل شوید و بدن را صاف و میان‌تنه را درگیر نگه دارید.
۴. بدن را تا جایی پایین ببرید که بتوانید کنترل و انقباض شکم را حفظ کنید.
۵. لحظه‌ای در پایین مکث کنید، سپس بدن را آرام به وضعیت شروع بالا ببرید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0805.gif', 'abs', 'obliques,hip-flexors', '1. Attach a suspension trainer to a high anchor point and adjust the straps to waist height.
2. Stand facing away from the anchor point and hold the handles with your arms extended in front of you.
3. Lean forward at the waist, keeping your body straight and your core engaged.
4. Lower your body as far as you can while maintaining control and tension in your abs.
5. Pause for a moment at the bottom, then slowly raise your body back up to the starting position.
6. Repeat for the desired number of repetitions.', '0805') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0806', 'شنا سوئدی معلق', 'Suspended push-up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها، میان‌تنه', '۱. تی‌آر‌ایکس را در ارتفاع مناسب تنظیم کنید.
۲. پشت به نقطه اتصال بایستید و دستگیره‌ها را از رو بگیرید.
۳. پاها را جلو ببرید و بدن را به جلو متمایل کنید تا وزن روی تی‌آر‌ایکس قرار گیرد.
۴. بدن را از سر تا پاشنه صاف نگه دارید، میان‌تنه را درگیر کنید و سینه را به سمت دستگیره‌ها پایین ببرید.
۵. با فشار سینه و دست‌ها به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0806.gif', 'chest', 'triceps,deltoids,abs', '1. Find a suspension trainer and adjust it to an appropriate height.
2. Stand facing away from the anchor point and hold the handles with an overhand grip.
3. Walk your feet forward, leaning your body forward until your weight is supported by the suspension trainer.
4. Keep your body straight from head to heels, engage your core, and lower your chest towards the handles.
5. Push through your chest and arms to return to the starting position.
6. Repeat for the desired number of repetitions.', '0806') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0807', 'کرانچ معکوس معلق', 'Suspended reverse crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و زانوها را به سمت سینه بالا بیاورید و لگن را به سمت دنده‌ها جمع کنید.
۳. لحظه‌ای در بالا مکث کنید، سپس زانوها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0807.gif', 'abs', 'hip-flexors', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your knees up towards your chest, curling your pelvis towards your ribcage.
3. Pause for a moment at the top, then slowly lower your knees back down to the starting position.
4. Repeat for the desired number of repetitions.', '0807') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0808', 'قایقی معلق', 'Suspended row', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'جلو بازو، شانه‌ها', '۱. تی‌آر‌ایکس را در ارتفاع مناسب تنظیم کنید.
۲. رو به تکیه‌گاه بایستید و پاها را به اندازه عرض شانه باز کنید.
۳. دستگیره‌ها را از رو با کف دست‌های رو به هم بگیرید.
۴. به عقب متمایل شوید، بدن را صاف و پاشنه‌ها را روی زمین نگه دارید.
۵. سینه را به سمت دستگیره‌ها بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در بالا مکث کنید، سپس آرام به وضعیت شروع پایین بیایید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0808.gif', 'upper-back', 'biceps,deltoids', '1. Set up a suspension trainer at an appropriate height.
2. Stand facing the anchor point with your feet shoulder-width apart.
3. Hold the handles with an overhand grip, palms facing each other.
4. Lean back, keeping your body straight and your heels on the ground.
5. Pull your chest towards the handles, squeezing your shoulder blades together.
6. Pause for a moment at the top, then slowly lower yourself back to the starting position.
7. Repeat for the desired number of repetitions.', '0808') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0809', 'اسکوات اسپلیت معلق', 'Suspended split squat', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'چهارسر ران', 'سرینی (باسن)، همسترینگ (پشت ران)، ساق پا', '۱. پشت به تی‌آر‌ایکس بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. یک پا را جلو دراز کنید و روی پا را در جای پای تی‌آر‌ایکس قرار دهید.
۳. پای تکیه‌گاه را خم کنید و به حالت لانج پایین بروید، سینه را بالا و زانو را در راستای پنجه نگه دارید.
۴. با فشار پاشنه به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید، سپس پا را عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0809.gif', 'quadriceps', 'gluteal,hamstring,calves', '1. Stand facing away from a suspension trainer with your feet shoulder-width apart.
2. Extend one leg forward and place the top of your foot in the foot cradle of the suspension trainer.
3. Bend your standing leg and lower your body down into a lunge position, keeping your chest up and your knee in line with your toes.
4. Push through your heel to return to the starting position.
5. Repeat for the desired number of repetitions, then switch legs.', '0809') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3433', 'ضربات پای شناگر (نسخه ۲)', 'Swimmer kicks v. 2 (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، ساق پا', '۱. روی تشک دمر دراز بکشید و دست‌ها را بالای سر دراز کنید.
۲. میان‌تنه را درگیر کنید و همزمان سینه و پاها را از زمین بلند کنید.
۳. پاها را مانند شنا کردن به صورت قیچی بالا و پایین ضربه بزنید.
۴. به تعداد تکرار دلخواه ضربه زدن را ادامه دهید.
۵. سینه و پاها را به وضعیت شروع پایین بیاورید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3433.gif', 'gluteal', 'hamstring,quadriceps,calves', '1. Lie face down on a mat with your arms extended overhead.
2. Engage your core and lift your chest and legs off the ground simultaneously.
3. Kick your legs up and down in a fluttering motion, as if you were swimming.
4. Continue kicking for the desired number of repetitions.
5. Lower your chest and legs back down to the starting position.', '3433') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1753', 'دیپ سه نیمکت', 'Three bench dip', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت بنشینید و لبه آن را با انگشتان رو به جلو بگیرید.
۲. باسن را از نیمکت جلو ببرید و وزن بدن را روی دست‌ها نگه دارید.
۳. آرنج‌ها را خم کنید و بدن را پایین ببرید تا بازوها موازی زمین شوند.
۴. خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1753.gif', 'triceps', 'chest,deltoids', '1. Sit on a bench with your hands gripping the edge, fingers pointing forward.
2. Slide your butt off the bench, supporting your weight with your hands.
3. Bend your elbows and lower your body until your upper arms are parallel to the ground.
4. Push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '1753') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2459', 'برگرداندن لاستیک', 'Tire flip', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، میان‌تنه', '۱. رو به لاستیک بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. زانوها را خم کنید و از لگن خم شوید و به حالت اسکوات پایین بروید.
۳. دست‌ها را پایین ببرید و لبه پایین لاستیک را با دو دست و انگشتان رو به خود بگیرید.
۴. باسن و عضلات پا را درگیر کنید و با فشار انفجاری پاها لاستیک را از زمین بلند کنید.
۵. هنگام برگشتن لاستیک، با قدرت بالاتنه آن را هدایت و کنترل کنید.
۶. وقتی لاستیک کاملاً برگشت، سریع عقب بروید و وضعیت خود را دوباره تنظیم کنید.
۷. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2459.gif', 'gluteal', 'hamstring,quadriceps,abs', '1. Stand with your feet shoulder-width apart, facing the tire.
2. Bend your knees and hinge at the hips, lowering into a squat position.
3. Reach down and grab the bottom edge of the tire with both hands, fingers facing towards you.
4. Engage your glutes and leg muscles, and explosively drive through your legs to lift the tire off the ground.
5. As the tire flips over, use your upper body strength to guide it and maintain control.
6. Once the tire is fully flipped, quickly step back and reset your stance.
7. Repeat for the desired number of repetitions.', '2459') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0811', 'ددلیفت تراپ‌بار', 'Trap bar deadlift', 'legs', 'پا', 'other', 'سایر', 'سرینی (باسن)', 'همسترینگ (پشت ران)، چهارسر ران، پایین کمر', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و تراپ‌بار روی زمین جلوی شما باشد.
۲. با خم کردن لگن و زانوها پایین بروید و دستگیره‌های تراپ‌بار را از رو بگیرید.
۳. کمر را صاف و سینه را بالا نگه دارید و با باز کردن لگن و زانوها تراپ‌بار را از زمین بلند کنید.
۴. هنگام بلند کردن، روی فشار پاشنه‌ها و انقباض باسن در اوج حرکت تمرکز کنید.
۵. با خم کردن لگن و زانوها تراپ‌بار را به زمین برگردانید و در تمام حرکت کمر را صاف نگه دارید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0811.gif', 'gluteal', 'hamstring,quadriceps,lower-back', '1. Stand with your feet shoulder-width apart and the trap bar on the ground in front of you.
2. Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with an overhand grip.
3. Keep your back straight and chest up as you begin to lift the trap bar off the ground by extending your hips and knees.
4. As you lift, focus on driving through your heels and squeezing your glutes at the top of the movement.
5. Lower the trap bar back down to the ground by bending at the hips and knees, keeping your back straight throughout the movement.
6. Repeat for the desired number of repetitions.', '0811') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0812', 'دیپ پشت بازو (پا روی نیمکت)', 'Triceps dip (bench leg)', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. لبه نیمکت بنشینید و لبه آن را با انگشتان رو به جلو بگیرید.
۲. پاها را جلو ببرید، باسن را از نیمکت جلو ببرید و دست‌ها را صاف کنید.
۳. آرنج‌ها را خم کنید و بدن را به سمت زمین پایین ببرید و کمر را نزدیک نیمکت نگه دارید.
۴. با فشار کف دست‌ها، دست‌ها را صاف کنید و به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0812.gif', 'triceps', 'chest,deltoids', '1. Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.
2. Walk your feet forward, sliding your butt off the bench, and straighten your arms.
3. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.
4. Push through your palms to straighten your arms and return to the starting position.
5. Repeat for the desired number of repetitions.', '0812') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0813', 'دیپ پشت بازو (بین دو نیمکت)', 'Triceps dip (between benches)', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت بنشینید و لبه آن را با انگشتان رو به جلو بگیرید.
۲. باسن را از نیمکت جلو ببرید و وزن بدن را روی دست‌ها نگه دارید.
۳. آرنج‌ها را خم کنید و بدن را به سمت زمین پایین ببرید و کمر را نزدیک نیمکت نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0813.gif', 'triceps', 'chest,deltoids', '1. Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.
2. Slide your butt off the bench, supporting your weight with your hands.
3. Bend your elbows and lower your body towards the ground, keeping your back close to the bench.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0813') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0815', 'دیپ پشت بازو روی زمین', 'Triceps dips floor', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. لبه صندلی یا نیمکت بنشینید و دست‌ها را کنار لگن با انگشتان رو به جلو بگذارید.
۲. باسن را از جلوی صندلی جلو ببرید و پاها را جلوی بدن دراز کنید.
۳. دست‌ها را صاف کنید و آرنج‌ها را کمی خم نگه دارید تا فشار روی پشت بازو بماند و به مفصل آرنج نیاید.
۴. آرنج‌ها را آرام خم کنید و بدن را به سمت زمین پایین ببرید تا آرنج‌ها حدود ۹۰ درجه شوند.
۵. در پایین حرکت، به صندلی فشار دهید و آرنج‌ها را صاف کنید و به وضعیت شروع برگردید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0815.gif', 'triceps', 'chest,deltoids', '1. Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.
2. Slide your butt off the front of the chair with your legs extended in front of you.
3. Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.
4. Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.
5. Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.
6. Repeat for the desired number of repetitions.', '0815') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0816', 'پرس پشت بازو', 'Triceps press', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'شانه‌ها', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و زانوها را کمی خم کنید.
۲. دست‌ها را صاف جلوی بدن و موازی زمین دراز کنید.
۳. آرنج‌ها را خم کنید و بدن را به سمت زمین پایین ببرید و بازوها را نزدیک پهلوها نگه دارید.
۴. لحظه‌ای در پایین مکث کنید، سپس خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0816.gif', 'triceps', 'deltoids', '1. Stand with your feet shoulder-width apart and your knees slightly bent.
2. Extend your arms straight out in front of you, parallel to the ground.
3. Bend your elbows and lower your body towards the ground, keeping your upper arms close to your sides.
4. Pause for a moment at the bottom, then push yourself back up to the starting position.
5. Repeat for the desired number of repetitions.', '0816') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0817', 'کشش پشت بازو', 'Triceps stretch', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'شانه‌ها', '۱. صاف بایستید یا بنشینید و کمر را صاف نگه دارید.
۲. یک دست را بالای سر ببرید و از آرنج خم کنید.
۳. دست مخالف را روی آرنج خم‌شده بگذارید و آرام به سمت سر بکشید.
۴. کشش را ۱۵ تا ۳۰ ثانیه نگه دارید و کشش ملایمی در پشت بازو حس کنید.
۵. کشش را رها کنید و با دست دیگر تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0817.gif', 'triceps', 'deltoids', '1. Stand or sit upright with your back straight.
2. Extend one arm overhead, bending it at the elbow.
3. Place your opposite hand on the bent elbow and gently pull it towards your head.
4. Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.
5. Release the stretch and repeat on the other arm.', '0817') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0871', 'کرانچ جمع‌شده', 'Tuck crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. دست‌ها را پشت سر بگذارید و آرنج‌ها را به سمت بیرون باز کنید.
۳. با درگیر کردن شکم، کتف‌ها را از زمین بلند کنید و زانوها را به سمت سینه بیاورید و همزمان بالاتنه را به سمت زانوها جمع کنید.
۴. لحظه‌ای در بالا مکث کنید، سپس کتف‌ها را آرام پایین بیاورید و پاها را به وضعیت شروع صاف کنید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0871.gif', 'abs', 'hip-flexors', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Place your hands behind your head with your elbows pointing outwards.
3. Engaging your abs, lift your shoulder blades off the ground and bring your knees towards your chest, simultaneously curling your upper body towards your knees.
4. Pause for a moment at the top, then slowly lower your shoulder blades and extend your legs back to the starting position.
5. Repeat for the desired number of repetitions.', '0871') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0818', 'زیربغل با دستگیره موازی دوتایی', 'Twin handle parallel grip lat pulldown', 'back', 'پشت و زیربغل', 'cable', 'سیم‌کش', 'زیربغل', 'جلو بازو، متوازی‌الاضلاع، دلتوئید خلفی', '۱. ارتفاع صندلی را تنظیم کنید و رو به سیم‌کش قرار بگیرید.
۲. دستگیره‌ها را از رو و به اندازه عرض شانه بگیرید.
۳. بنشینید و ران‌ها را زیر پدهای ران قرار دهید و کف پاها را روی زمین نگه دارید.
۴. کمی به عقب متمایل شوید، سینه را بالا نگه دارید و ستون فقرات را در حالت طبیعی حفظ کنید.
۵. دستگیره‌ها را به سمت بالای سینه پایین بکشید و کتف‌ها را به هم فشار دهید.
۶. لحظه‌ای در پایین حرکت مکث کنید و انقباض زیربغل را حس کنید.
۷. دستگیره‌ها را آرام رها کنید و به وضعیت شروع برگردید.
۸. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0818.gif', 'upper-back', 'biceps,deltoids', '1. Adjust the seat height and position yourself facing the cable machine.
2. Grasp the handles with an overhand grip, hands shoulder-width apart.
3. Sit down and position your thighs under the thigh pads, keeping your feet flat on the floor.
4. Lean back slightly and keep your chest up, maintaining a neutral spine.
5. Pull the handles down towards your upper chest, squeezing your shoulder blades together.
6. Pause for a moment at the bottom of the movement, feeling the contraction in your lats.
7. Slowly release the handles and return to the starting position.
8. Repeat for the desired number of repetitions.', '0818') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1466', 'بالا آوردن لگن با چرخش', 'Twist hip lift', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'پهلوها، همسترینگ (پشت ران)', '۱. به پشت دراز بکشید، زانوها خم و کف پاها روی زمین باشد.
۲. برای حمایت دست‌ها را کنار بدن بگذارید.
۳. باسن را درگیر کنید و لگن را از زمین بلند کنید تا بدن از زانو تا شانه یک خط صاف بسازد.
۴. در حالی که لگن بالا است، پایین‌تنه را به راست بچرخانید و زانوها را به سمت زمین ببرید.
۵. به وضعیت شروع برگردید و چرخش را به سمت چپ تکرار کنید.
۶. به تعداد تکرار دلخواه، چرخش‌ها را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1466.gif', 'gluteal', 'obliques,hamstring', '1. Lie on your back with your knees bent and feet flat on the ground.
2. Place your hands by your sides for support.
3. Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.
4. While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.
5. Return to the starting position and repeat the twist to the left side.
6. Continue alternating twists for the desired number of repetitions.', '1466') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2802', 'بالا آوردن پا با چرخش', 'Twisted leg raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، خم‌کننده ران', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها کنار بدن باشد.
۲. دست‌ها را برای حمایت زیر باسن بگذارید.
۳. شکم را درگیر کنید و هر دو پا را صاف از زمین بلند کنید.
۴. هنگام بلند کردن پاها، لگن را به یک طرف بچرخانید و پاها را به سمت شانه مخالف ببرید.
۵. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۶. حرکت را تکرار کنید و این بار لگن را به طرف دیگر بچرخانید.
۷. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2802.gif', 'abs', 'obliques,hip-flexors', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Place your hands under your glutes for support.
3. Engage your abs and lift both legs off the ground, keeping them straight.
4. As you lift your legs, twist your hips to one side, bringing your legs towards your opposite shoulder.
5. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
6. Repeat the movement, this time twisting your hips to the other side.
7. Continue alternating sides for the desired number of repetitions.', '2802') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2801', 'بالا آوردن پا با چرخش (بانوان)', 'Twisted leg raise (female)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، خم‌کننده ران', '۱. به پشت صاف دراز بکشید، پاها صاف و دست‌ها کنار بدن باشد.
۲. زانوها را خم کنید و پاها را از زمین بلند کنید و به سمت سینه بیاورید.
۳. هنگام بلند کردن پاها، لگن را به یک طرف بچرخانید و زانوها را به سمت شانه مخالف ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. حرکت را تکرار کنید و این بار لگن را به طرف دیگر بچرخانید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2801.gif', 'abs', 'obliques,hip-flexors', '1. Lie flat on your back with your legs extended and your arms by your sides.
2. Bend your knees and lift your legs off the ground, bringing them towards your chest.
3. As you lift your legs, twist your hips to one side, bringing your knees towards your opposite shoulder.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat the movement, this time twisting your hips to the other side.
6. Continue alternating sides for the desired number of repetitions.', '2801') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3231', 'لمس پنجه با دو دست', 'Two toe touch (male)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'فیله کمر', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و دست‌ها را به طرفین باز کنید.
۲. از کمر به جلو خم شوید و کمر را صاف و زانوها را کمی خم نگه دارید.
۳. با پاهای صاف، هر دو دست را به سمت پنجه پاها پایین ببرید.
۴. لحظه‌ای در پایین مکث کنید، سپس آرام به وضعیت شروع برگردید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3231.gif', 'lower-back', 'hamstring,gluteal', '1. Stand with your feet shoulder-width apart and your arms extended out to the sides.
2. Bend forward at the waist, keeping your back straight and your knees slightly bent.
3. Reach down towards your toes with both hands, keeping your legs straight.
4. Pause for a moment at the bottom, then slowly return to the starting position.
5. Repeat for the desired number of repetitions.', '3231') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1365', 'کشش بالای کمر', 'Upper back stretch', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'بالای پشت', 'شانه‌ها', '۱. صاف بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. دست‌ها را صاف جلوی بدن و موازی زمین دراز کنید.
۳. انگشتان را در هم قفل کنید و کف دست‌ها را رو به بیرون بچرخانید.
۴. دست‌ها را آرام بالای سر ببرید و صاف و موازی هم نگه دارید.
۵. هنگام بالا بردن دست‌ها کتف‌ها را به هم فشار دهید.
۶. کشش را ۱۵ تا ۳۰ ثانیه نگه دارید، سپس رها کرده و تکرار کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1365.gif', 'upper-back', 'deltoids', '1. Stand up straight with your feet shoulder-width apart.
2. Extend your arms straight in front of you, parallel to the ground.
3. Interlace your fingers and rotate your palms away from your body.
4. Slowly raise your arms overhead, keeping them straight and parallel to each other.
5. As you raise your arms, squeeze your shoulder blades together.
6. Hold the stretch for 15-30 seconds, then release and repeat.', '1365') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1366', 'سگ رو به بالا', 'Upward facing dog', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'فیله کمر', 'شانه‌ها، سینه', '۱. روی زمین دمر دراز بکشید و پاها را پشت سر دراز کنید.
۲. دست‌ها را کنار دنده‌های پایین روی زمین بگذارید، انگشتان رو به جلو.
۳. دست‌ها را محکم به زمین فشار دهید و صاف کنید و تنه و ران‌ها را از زمین بلند کنید.
۴. شانه‌ها را به عقب و پایین بچرخانید، سینه را باز کنید و نگاه را به سمت سقف ببرید.
۵. این وضعیت را برای چند نفس نگه دارید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1366.gif', 'lower-back', 'deltoids,chest', '1. Lie face down on the floor with your legs extended behind you.
2. Place your hands on the floor next to your lower ribs, fingers pointing forward.
3. Press your hands firmly into the floor and straighten your arms, lifting your torso and thighs off the ground.
4. Roll your shoulders back and down, opening your chest and lifting your gaze towards the ceiling.
5. Hold this position for a few breaths, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '1366') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3420', 'وی‌سیت روی زمین', 'V-sit on floor', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. روی زمین بنشینید و پاها را جلوی بدن دراز کنید.
۲. کمی به عقب متمایل شوید و پاها را صاف از زمین بلند کنید.
۳. همزمان بالاتنه را از زمین بلند کنید و دست‌ها را به سمت پاها ببرید.
۴. این وضعیت را چند ثانیه نگه دارید، سپس بالاتنه و پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3420.gif', 'abs', 'hip-flexors', '1. Sit on the floor with your legs extended in front of you.
2. Lean back slightly and lift your legs off the ground, keeping them straight.
3. Simultaneously, lift your upper body off the ground and reach your arms towards your legs.
4. Hold this position for a few seconds, then slowly lower your upper body and legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '3420') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0826', 'بالا آوردن پا عمودی (روی پارالل)', 'Vertical leg raise (on parallel bars)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران', '۱. از پارالل با دست‌های کاملاً صاف و بدن صاف آویزان شوید.
۲. میان‌تنه را درگیر کنید و پاها را صاف جلوی بدن بالا بیاورید.
۳. تا جایی بالا بیاورید که پاها موازی زمین یا کمی بالاتر باشند.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0826.gif', 'abs', 'hip-flexors', '1. Hang from the parallel bars with your arms fully extended and your body straight.
2. Engage your core and lift your legs up in front of you, keeping them straight.
3. Continue lifting until your legs are parallel to the ground or slightly higher.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0826') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1460', 'لانج راه رفتنی', 'Walking lunge', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید و پاها را به اندازه عرض شانه باز کنید.
۲. با پای راست یک گام به جلو بردارید و به حالت لانج پایین بروید.
۳. تنه را صاف و زانوی جلو را در راستای مچ پا نگه دارید.
۴. با فشار پای راست، پای چپ را جلو بیاورید و با پای چپ به حالت لانج بروید.
۵. با سرعتی کنترل‌شده و ثابت، پاها را یکی در میان عوض کنید و به جلو راه بروید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1460.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart.
2. Take a step forward with your right leg, lowering your body into a lunge position.
3. Keep your torso upright and your front knee aligned with your ankle.
4. Push off with your right foot and bring your left foot forward, stepping into a lunge position with your left leg.
5. Continue alternating legs and walking forward, maintaining a controlled and steady pace.
6. Repeat for the desired number of repetitions.', '1460') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0830', 'دیپ نیمکت با وزنه', 'Weighted bench dip', 'arms', 'بازو', 'bodyweight', 'وزن بدن', 'پشت بازو', 'سینه، شانه‌ها', '۱. روی نیمکت بنشینید و لبه آن را با انگشتان رو به جلو بگیرید.
۲. باسن را از نیمکت جلو ببرید و وزن بدن را روی دست‌ها نگه دارید.
۳. با خم کردن آرنج‌ها بدن را پایین ببرید تا بازوها موازی زمین شوند.
۴. با صاف کردن دست‌ها خود را به وضعیت شروع بالا ببرید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0830.gif', 'triceps', 'chest,deltoids', '1. Sit on a bench with your hands gripping the edge, fingers pointing forward.
2. Slide your butt off the bench, supporting your weight with your hands.
3. Lower your body by bending your elbows until your upper arms are parallel to the floor.
4. Push yourself back up to the starting position by straightening your arms.
5. Repeat for the desired number of repetitions.', '0830') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2987', 'بارفیکس دست‌برعکس دست جمع با وزنه روی قفس دیپ', 'Weighted close grip chin-up on dip cage', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. جلوی قفس دیپ بایستید و میله‌های موازی را از زیر و به اندازه عرض شانه بگیرید.
۲. با دست‌های کاملاً صاف، پاهای جدا از زمین و بدن صاف از میله‌ها آویزان شوید.
۳. عضلات پشت را درگیر کنید و بدن را به سمت میله‌ها بالا بکشید و آرنج‌ها را نزدیک پهلوها نگه دارید.
۴. تا جایی بالا بروید که چانه بالای میله‌ها باشد، سپس لحظه‌ای مکث کنید.
۵. بدن را آرام به وضعیت شروع پایین بیاورید و دست‌ها را کاملاً صاف کنید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2987.gif', 'upper-back', 'biceps,forearm', '1. Stand in front of the dip cage and grab the parallel bars with an underhand grip, hands shoulder-width apart.
2. Hang from the bars with your arms fully extended, feet off the ground, and body straight.
3. Engage your back muscles and pull your body up towards the bars, keeping your elbows close to your sides.
4. Continue pulling until your chin is above the bars, then pause for a moment.
5. Slowly lower your body back down to the starting position, fully extending your arms.
6. Repeat for the desired number of repetitions.', '2987') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3643', 'اسکوات قزاقی با وزنه', 'Weighted cossack squats (male)', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را بازتر از عرض شانه باز کنید و پنجه‌ها را کمی به بیرون بچرخانید.
۲. یک وزنه را با دو دست جلوی سینه نگه دارید.
۳. وزن را به یک طرف ببرید و با خم کردن زانوی همان طرف پایین بروید و پای دیگر را صاف نگه دارید.
۴. تا جایی که تعادل دارید و سینه بالا می‌ماند پایین بروید.
۵. با فشار پاشنه پای خم‌شده به وضعیت شروع برگردید.
۶. برای طرف دیگر تکرار کنید و پاها را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3643.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet wider than shoulder-width apart and toes pointing slightly outward.
2. Hold a weight in front of your chest with both hands.
3. Shift your weight to one side and lower your body by bending the knee of the side you shifted towards, while keeping the other leg straight.
4. Go as low as you can while maintaining balance and keeping your chest up.
5. Push through the heel of the bent leg to return to the starting position.
6. Repeat on the other side, alternating between legs.', '3643') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0832', 'کرانچ با وزنه', 'Weighted crunch', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها', '۱. به پشت صاف دراز بکشید، زانوها را خم کنید و کف پاها را روی زمین بگذارید.
۲. یک صفحه وزنه یا دمبل را روی سینه نگه دارید.
۳. شکم را درگیر کنید و بالاتنه را از زمین بلند کنید و به جلو خم شوید تا کتف‌ها از زمین جدا شوند.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0832.gif', 'abs', 'obliques', '1. Lie flat on your back with your knees bent and feet flat on the ground.
2. Hold a weight plate or dumbbell on your chest.
3. Engage your abs and lift your upper body off the ground, curling forward until your shoulder blades are off the ground.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0832') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3670', 'دراز و نشست زیرسینه با وزنه', 'Weighted decline sit-up', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. روی نیمکت زیرسینه دراز بکشید و پاها را زیر پدهای پا محکم کنید.
۲. دست‌ها را پشت سر یا ضربدری روی سینه بگذارید.
۳. شکم را درگیر کنید و بالاتنه را آرام از نیمکت بلند کنید و به جلو خم شوید تا تنه عمود بر زمین شود.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3670.gif', 'abs', 'hip-flexors,lower-back', '1. Lie flat on a decline bench with your feet secured under the foot pads.
2. Place your hands behind your head or across your chest.
3. Engage your abs and slowly lift your upper body off the bench, curling forward until your torso is perpendicular to the ground.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '3670') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0833', 'ساق پا خرکی با وزنه', 'Weighted donkey calf raise', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'ساق پا', 'همسترینگ (پشت ران)، سرینی (باسن)', '۱. روی سکوی بلند بایستید، پنجه‌ها روی لبه و پاشنه‌ها آزاد باشند.
۲. برای حمایت یک جسم ثابت را بگیرید.
۳. با باز کردن مچ پاها پاشنه‌ها را تا جای ممکن بالا ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس پاشنه‌ها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0833.gif', 'calves', 'hamstring,gluteal', '1. Stand on a raised platform with your toes on the edge and your heels hanging off.
2. Hold onto a stable object for support.
3. Raise your heels as high as possible by extending your ankles.
4. Pause for a moment at the top, then slowly lower your heels back down to the starting position.
5. Repeat for the desired number of repetitions.', '0833') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_1310', 'شنا سوئدی با فرود و وزنه', 'Weighted drop push up', 'chest', 'سینه', 'bodyweight', 'وزن بدن', 'سینه', 'پشت بازو، شانه‌ها', '۱. در وضعیت پلانک با دست صاف قرار بگیرید، دست‌ها کمی بازتر از عرض شانه و پاها جفت باشد.
۲. سینه را به سمت زمین پایین ببرید و آرنج‌ها را نزدیک بدن نگه دارید.
۳. وقتی سینه کمی بالاتر از زمین قرار گرفت، به صورت انفجاری بالا بروید و دست‌ها را از زمین جدا کنید.
۴. هنگام بالا رفتن، سریع دست‌ها را به طرفین و کمی جلوتر ببرید و اجازه دهید بدن به سمت زمین پایین بیاید.
۵. با دست‌ها در فاصله بازتر خود را بگیرید و بلافاصله دوباره سینه را به سمت زمین پایین ببرید.
۶. حرکت شنا را تکرار کنید و این بار با دست‌ها در فاصله جمع‌تر فرود بیایید.
۷. به تعداد تکرار دلخواه فاصله باز و جمع دست‌ها را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/1310.gif', 'chest', 'triceps,deltoids', '1. Start in a high plank position with your hands slightly wider than shoulder-width apart and your feet together.
2. Lower your chest towards the ground, keeping your elbows close to your body.
3. Once your chest is just above the ground, explosively push yourself up, lifting your hands off the ground.
4. As you push up, quickly move your hands out to the sides and slightly forward, allowing your body to drop down towards the ground.
5. Catch yourself with your hands in the wider position and immediately lower your chest towards the ground again.
6. Repeat the push-up motion, dropping down and catching yourself with your hands in the narrower position.
7. Continue alternating between the wider and narrower hand positions for the desired number of repetitions.', '1310') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0834', 'نشر جلو با صفحه وزنه', 'Weighted front raise', 'shoulders', 'سرشانه', 'bodyweight', 'وزن بدن', 'سرشانه', 'جلو بازو، ساعد', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل با کف دست رو به ران‌ها بگیرید.
۲. با دست‌های صاف و بازدم، دمبل‌ها را جلوی بدن تا سطح شانه بالا بیاورید.
۳. لحظه‌ای در بالا مکث کنید، سپس با دم دمبل‌ها را آرام به وضعیت شروع پایین بیاورید.
۴. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0834.gif', 'deltoids', 'biceps,forearm', '1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your thighs.
2. Keeping your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.
3. Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.
4. Repeat for the desired number of repetitions.', '0834') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0866', 'بالا آوردن پا و لگن در حالت آویزان با وزنه', 'Weighted hanging leg-hip raise', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'خم‌کننده ران، پایین کمر', '۱. از میله بارفیکس با دست‌های کاملاً باز و کف دست رو به جلو آویزان شوید.
۲. میان‌تنه را درگیر کنید و پاها را صاف جلوی بدن بالا بیاورید.
۳. تا جایی بالا بیاورید که پاها موازی زمین یا کمی بالاتر باشند.
۴. لحظه‌ای در بالا مکث کنید، سپس پاها را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0866.gif', 'abs', 'hip-flexors,lower-back', '1. Hang from a pull-up bar with your arms fully extended and your palms facing away from you.
2. Engage your core and lift your legs up in front of you, keeping them straight.
3. Continue lifting until your legs are parallel to the ground or slightly higher.
4. Pause for a moment at the top, then slowly lower your legs back down to the starting position.
5. Repeat for the desired number of repetitions.', '0866') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0835', 'فیله کمر با وزنه (روی توپ تعادلی)', 'Weighted hyperextension (on stability ball)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'فیله کمر', 'سرینی (باسن)، همسترینگ (پشت ران)', '۱. دمر روی توپ تعادلی قرار بگیرید؛ لگن روی توپ و برای ثبات کف پاها به دیوار تکیه داشته باشد.
۲. دست‌ها را پشت سر بگذارید یا روی سینه ضربدری کنید.
۳. میان‌تنه را درگیر کنید و بالاتنه را آرام از توپ بلند کنید و کمر را باز کنید تا بدن یک خط صاف بسازد.
۴. لحظه‌ای در بالا مکث کنید، سپس بالاتنه را آرام به وضعیت شروع برگردانید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0835.gif', 'lower-back', 'gluteal,hamstring', '1. Position yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.
2. Place your hands behind your head or cross them over your chest.
3. Engage your core and slowly lift your upper body off the ball, extending your back until your body forms a straight line.
4. Pause for a moment at the top, then slowly lower your upper body back down to the starting position.
5. Repeat for the desired number of repetitions.', '0835') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3641', 'گام زانو زده با تاب وزنه', 'Weighted kneeling step with swing', 'shoulders', 'سرشانه', 'bodyweight', 'وزن بدن', 'سرشانه', 'پشت بازو، میان‌تنه', '۱. در حالت زانو زده قرار بگیرید، زانوها به اندازه عرض لگن باز و کمر صاف باشد.
۲. در هر دست یک وزنه بگیرید و دست‌ها را صاف رو به پایین جلوی بدن نگه دارید.
۳. میان‌تنه را درگیر کنید و وزنه‌ها را با دست‌های صاف به بالا و بالای سر تاب دهید.
۴. وزنه‌ها را به وضعیت شروع پایین بیاورید و به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3641.gif', 'deltoids', 'triceps,abs', '1. Start in a kneeling position with your knees hip-width apart and your back straight.
2. Hold a weight in each hand, with your arms extended straight down in front of you.
3. Engage your core and swing the weights up and overhead, keeping your arms straight.
4. Lower the weights back down to the starting position and repeat for the desired number of repetitions.', '3641') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3644', 'لانج با تاب وزنه', 'Weighted lunge with swing', 'legs', 'پا', 'bodyweight', 'وزن بدن', 'سرینی (باسن)', 'چهارسر ران، همسترینگ (پشت ران)، ساق پا', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک وزنه بگیرید.
۲. با پای راست یک گام به جلو بردارید و به حالت لانج پایین بروید.
۳. هنگام لانج به جلو، وزنه‌ها را با دست‌های صاف به جلو و بالا تاب دهید.
۴. با فشار پای راست به وضعیت شروع برگردید و وزنه‌ها را پایین تاب دهید.
۵. با پای چپ تکرار کنید و به تعداد تکرار دلخواه پاها را یکی در میان عوض کنید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3644.gif', 'gluteal', 'quadriceps,hamstring,calves', '1. Stand with your feet shoulder-width apart, holding a weight in each hand.
2. Take a step forward with your right foot, lowering your body into a lunge position.
3. As you lunge forward, swing the weights forward and upward, keeping your arms straight.
4. Push off with your right foot and return to the starting position, swinging the weights back down.
5. Repeat with your left foot and continue alternating legs for the desired number of repetitions.', '3644') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3286', 'ماسل‌آپ با وزنه', 'Weighted muscle up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، پشت بازو، شانه‌ها، سینه', '۱. از میله بارفیکس با کف دست رو به جلو و دست‌ها کمی بازتر از عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و با هدایت سینه، بدن را به سمت میله بالا بکشید.
۳. در اوج حرکت، گرفتن را تغییر دهید تا کف دست‌ها رو به شما باشد.
۴. تا جایی خود را بالا بکشید که سینه به میله برسد، سپس لحظه‌ای مکث کنید.
۵. آرام و با کنترل کامل به وضعیت شروع پایین بیایید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3286.gif', 'upper-back', 'biceps,triceps,deltoids,chest', '1. Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.
2. Engage your core and pull your body up towards the bar, leading with your chest.
3. As you reach the top of the movement, transition your grip so that your palms are facing towards you.
4. Continue pulling yourself up until your chest reaches the bar, then pause for a moment.
5. Slowly lower yourself back down to the starting position, maintaining control throughout the movement.
6. Repeat for the desired number of repetitions.', '3286') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3312', 'ماسل‌آپ با وزنه (روی میله)', 'Weighted muscle up (on bar)', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، پشت بازو، شانه‌ها، ساعد', '۱. از میله بارفیکس با کف دست رو به جلو و دست‌ها کمی بازتر از عرض شانه آویزان شوید.
۲. میان‌تنه را درگیر کنید و کتف‌ها را به پایین و عقب بکشید.
۳. آرنج‌ها را خم کنید و سینه را به سمت میله بکشید و بدن را صاف نگه دارید.
۴. وقتی سینه به میله رسید، با دست‌ها به پایین فشار دهید و آرنج‌ها را به عقب ببرید تا بدن بالای میله برود.
۵. در اوج حرکت مکث کنید، سپس آرام به وضعیت شروع پایین بیایید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3312.gif', 'upper-back', 'biceps,triceps,deltoids,forearm', '1. Start by hanging from a pull-up bar with your palms facing away from you and your hands slightly wider than shoulder-width apart.
2. Engage your core and pull your shoulder blades down and back.
3. Bend your elbows and pull your chest towards the bar, keeping your body straight.
4. Once your chest reaches the bar, push down with your hands and drive your elbows back, lifting your body above the bar.
5. Pause at the top of the movement, then slowly lower yourself back down to the starting position.
6. Repeat for the desired number of repetitions.', '3312') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_3290', 'بارفیکس تک‌دست با وزنه', 'Weighted one hand pull up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. میله بارفیکس را از رو و کمی بازتر از عرض شانه بگیرید.
۲. با دست کاملاً صاف و بدن صاف از میله آویزان شوید.
۳. میان‌تنه را درگیر کنید و با خم کردن آرنج و انقباض عضلات پشت بدن را به سمت میله بالا بکشید.
۴. تا جایی بالا بروید که چانه بالای میله قرار بگیرد.
۵. بدن را با کنترل به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/3290.gif', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
2. Hang from the bar with your arm fully extended and your body straight.
3. Engage your core and pull your body up towards the bar by bending your elbow and squeezing your back muscles.
4. Continue pulling until your chin is above the bar.
5. Lower your body back down to the starting position with control.
6. Repeat for the desired number of repetitions.', '3290') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0840', 'کرانچ بالای سر با وزنه (روی توپ تعادلی)', 'Weighted overhead crunch (on stability ball)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، پایین کمر', '۱. روی توپ تعادلی بنشینید، کف پاها روی زمین و زانوها ۹۰ درجه خم باشد.
۲. یک صفحه وزنه یا دمبل را با دو دست بگیرید و دست‌ها را بالای سر دراز کنید.
۳. شکم را درگیر کنید و تنه را آرام به جلو خم کنید و سینه را به سمت زانوها ببرید.
۴. لحظه‌ای در بالا مکث کنید، سپس تنه را آرام به وضعیت شروع پایین بیاورید.
۵. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0840.gif', 'abs', 'obliques,lower-back', '1. Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.
2. Hold a weight plate or dumbbell with both hands and extend your arms overhead.
3. Engage your abs and slowly curl your torso forward, bringing your chest towards your knees.
4. Pause for a moment at the top, then slowly lower your torso back to the starting position.
5. Repeat for the desired number of repetitions.', '0840') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0841', 'بارفیکس با وزنه', 'Weighted pull-up', 'back', 'پشت و زیربغل', 'bodyweight', 'وزن بدن', 'زیربغل', 'جلو بازو، ساعد', '۱. میله بارفیکس را از رو و کمی بازتر از عرض شانه بگیرید.
۲. با دست‌های کاملاً صاف و بدن صاف از میله آویزان شوید.
۳. عضلات پشت را درگیر کنید و بدن را به سمت میله بالا بکشید و آرنج‌ها را نزدیک بدن نگه دارید.
۴. تا جایی بالا بروید که چانه بالای میله قرار بگیرد.
۵. لحظه‌ای در بالا مکث کنید، سپس بدن را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0841.gif', 'upper-back', 'biceps,forearm', '1. Grab the pull-up bar with an overhand grip, slightly wider than shoulder-width apart.
2. Hang from the bar with your arms fully extended and your body straight.
3. Engage your back muscles and pull your body up towards the bar, keeping your elbows close to your body.
4. Continue pulling until your chin is above the bar.
5. Pause for a moment at the top, then slowly lower your body back down to the starting position.
6. Repeat for the desired number of repetitions.', '0841') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0844', 'چرخش دست با صفحه وزنه', 'Weighted round arm', 'shoulders', 'سرشانه', 'bodyweight', 'وزن بدن', 'سرشانه', 'پشت بازو، بالای پشت', '۱. بایستید، پاها را به اندازه عرض شانه باز کنید و در هر دست یک دمبل بگیرید.
۲. زانوها را کمی خم کنید و از لگن به جلو خم شوید و کمر را صاف نگه دارید.
۳. دست‌ها را با آرنج‌های کمی خم به طرفین بالا ببرید.
۴. تا جایی بالا ببرید که دست‌ها موازی زمین شوند.
۵. لحظه‌ای در بالا مکث کنید، سپس دست‌ها را آرام به وضعیت شروع پایین بیاورید.
۶. به تعداد تکرار دلخواه انجام دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0844.gif', 'deltoids', 'triceps,upper-back', '1. Stand with your feet shoulder-width apart and hold a dumbbell in each hand.
2. Bend your knees slightly and hinge forward at the hips, keeping your back straight.
3. Raise your arms out to the sides, keeping a slight bend in your elbows.
4. Continue lifting your arms until they are parallel to the ground.
5. Pause for a moment at the top, then slowly lower your arms back down to the starting position.
6. Repeat for the desired number of repetitions.', '0844') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0846', 'چرخش روسی با وزنه', 'Weighted russian twist', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، پایین کمر', '۱. روی زمین بنشینید، زانوها خم و کف پاها روی زمین باشد.
۲. یک وزنه یا توپ طبی را با دو دست جلوی سینه نگه دارید.
۳. کمی به عقب متمایل شوید و کمر را صاف و میان‌تنه را درگیر نگه دارید.
۴. تنه را آرام به راست بچرخانید و وزنه یا توپ را به سمت زمین در سمت راست ببرید.
۵. لحظه‌ای مکث کنید، سپس تنه را به چپ بچرخانید و وزنه یا توپ را به سمت زمین در سمت چپ ببرید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0846.gif', 'abs', 'obliques,lower-back', '1. Sit on the ground with your knees bent and your feet flat on the floor.
2. Hold a weight or medicine ball with both hands in front of your chest.
3. Lean back slightly, keeping your back straight and your core engaged.
4. Slowly twist your torso to the right, bringing the weight or medicine ball towards the floor on your right side.
5. Pause for a moment, then twist your torso to the left, bringing the weight or medicine ball towards the floor on your left side.
6. Continue alternating sides for the desired number of repetitions.', '0846') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_0845', 'چرخش روسی با وزنه (پاها بالا)', 'Weighted russian twist (legs up)', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، خم‌کننده ران', '۱. روی زمین بنشینید، زانوها خم و پاها جفت و از زمین بلند باشند.
۲. وزنه را با دو دست جلوی سینه نگه دارید و آرنج‌ها را کمی خم کنید.
۳. برای درگیر کردن عضلات میان‌تنه کمی به عقب متمایل شوید.
۴. تنه را به راست بچرخانید و وزنه را به سمت زمین در سمت راست ببرید.
۵. لحظه‌ای مکث کنید، سپس تنه را به چپ بچرخانید و وزنه را به سمت زمین در سمت چپ ببرید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/0845.gif', 'abs', 'obliques,hip-flexors', '1. Sit on the ground with your knees bent and feet lifted off the ground, keeping your legs together.
2. Hold the weight with both hands in front of your chest, keeping your elbows slightly bent.
3. Lean back slightly to engage your core muscles.
4. Twist your torso to the right, bringing the weight towards the ground on your right side.
5. Pause for a moment, then twist your torso to the left, bringing the weight towards the ground on your left side.
6. Continue alternating sides for the desired number of repetitions.', '0845') ON CONFLICT(id) DO UPDATE SET name_fa = excluded.name_fa, name_en = excluded.name_en, category = excluded.category, category_fa = excluded.category_fa, equipment = excluded.equipment, equipment_fa = excluded.equipment_fa, target_muscles = excluded.target_muscles, secondary_muscles = excluded.secondary_muscles, instructions_fa = excluded.instructions_fa, gif_url = excluded.gif_url, muscles_primary = excluded.muscles_primary, muscles_secondary = excluded.muscles_secondary, instructions_en = excluded.instructions_en, source_id = excluded.source_id;
INSERT INTO exercises (id, name_fa, name_en, category, category_fa, equipment, equipment_fa, target_muscles, secondary_muscles, instructions_fa, gif_url, muscles_primary, muscles_secondary, instructions_en, source_id) VALUES ('ex_db_2371', 'چرخش روسی با وزنه (نسخه ۲)', 'Weighted russian twist v. 2', 'core', 'شکم و میان‌تنه', 'bodyweight', 'وزن بدن', 'شکم', 'پهلوها، پایین کمر', '۱. روی زمین بنشینید، زانوها خم و کف پاها روی زمین باشد.
۲. وزنه را با دو دست جلوی سینه نگه دارید.
۳. برای درگیر کردن عضلات میان‌تنه کمی به عقب متمایل شوید.
۴. تنه را به راست بچرخانید و وزنه را به سمت راست بدن ببرید.
۵. لحظه‌ای مکث کنید، سپس تنه را به چپ بچرخانید و وزنه را به سمت چپ بدن ببرید.
۶. به تعداد تکرار دلخواه، طرفین را یکی در میان ادامه دهید.', 'https://cdn.jsdelivr.net/gh/omercotkd/exercises-gifs@ebf642cd90fdf73a6c73e7127e93b607b12c229e/assets/2371.gif', 'abs', 'obliques,lower-back', '1. Sit on the ground with your knees bent and feet flat on the floor.
